import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IPageBbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsComments";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated and filtered comment listing for a post.
 *
 * This test verifies the comment search functionality including pagination and filtering:
 *
 * 1. Create a new user (User A) and a random category id (as required for post creation).
 * 2. Register a new post as User A.
 * 3. Add several comments to this post:
 *    - Some root/top-level comments (no parent)
 *    - Nested replies (parent_id set to existing comment ids)
 *    - At least 5 comments in total
 * 4. Run patchByPostid (list/search) with:
 *    - No filter: all (not deleted) comments
 *    - Filter by author_id (should return only that author's comments)
 *    - Filter by parent_id (only direct replies to a given comment)
 *    - Filter by created_after/created_before (subsets by date)
 *    - Nonsensical filters (fake user or out-of-bounds date): should return empty result
 *    - Pagination: restrict 'limit' and get multiple pages, check all returned and no overlap
 * 5. After each query, assert:
 *    - Response type shape with typia.assert
 *    - All returned comments conform to expected filter
 *    - Pagination structure/behavior
 *    - No deleted comments in result
 *
 * Edge Cases:
 * - Empty list returned for nonsensical filters
 * - Invalid/edge date ranges return none
 *
 * This test does not check deletion (API surface not present), but verifies all search/result correctness for realistic comment search workflows.
 */
export async function test_api_bbs_test_list_comments_for_post_with_various_filters(connection: api.IConnection) {
  // Step 1: Create a new user (User A)
  const userRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphabets(6) + "@example.com",
      password: "P@ssword1!",
      bio: "Test user A",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  // Step 2: Create a post with a random category id (simulate category)
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: "Test post for comment listing",
      content: "This post is used for testing comment list queries.",
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // Step 3: Add several comments to the post (all as userA for this test)
  const commentContents = [
    "Root comment one.",
    "Root comment two.",
    "Root comment three.",
    "This is a nested reply to comment one.",
    "This is a nested reply to comment two.",
    "Another reply to comment one.",
  ];
  // Create root comments first
  const rootComments: bbsComments[] = [];
  for (let i = 0; i < 3; ++i) {
    const c = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: { content: commentContents[i] } satisfies bbsComments.ICreate,
    });
    typia.assert(c);
    rootComments.push(c);
  }
  // Create nested replies (as replies to root comments)
  const nestedComments: bbsComments[] = [];
  const nestedInfo = [
    { content: commentContents[3], parent: rootComments[0] },
    { content: commentContents[4], parent: rootComments[1] },
    { content: commentContents[5], parent: rootComments[0] },
  ];
  for (const n of nestedInfo) {
    const c = await api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: n.content,
        parent_id: n.parent.id,
      } satisfies bbsComments.ICreate,
    });
    typia.assert(c);
    nestedComments.push(c);
  }
  const allComments = [...rootComments, ...nestedComments];

  // Helper for fetching recent timestamps (spread to provide created_after/created_before filters)
  const getIsoDateDelta = (date: string, deltaMs: number) =>
    new Date(new Date(date).getTime() + deltaMs).toISOString();

  // Step 4a: Query with no filter (should return all created comments)
  const allPage = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: {},
  });
  typia.assert(allPage);
  for (const c of allPage.data) {
    // All returned comments should be among created, not deleted
    TestValidator.predicate("all comments exist in known comments")(
      allComments.some(ac => ac.id === c.id && !c.deleted_at),
    );
  }
  TestValidator.equals("comment count - no filter")(allComments.length)(allPage.data.length);

  // Step 4b: Filter by author_id (returns only this user's comments)
  const byAuthor = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { author_id: userA.id },
  });
  typia.assert(byAuthor);
  for (const c of byAuthor.data) {
    TestValidator.equals("author_id")(userA.id)(c.user_id);
    TestValidator.predicate("not deleted")(c.deleted_at == null);
  }

  // Step 4c: Filter by parent_id (e.g., replies to rootComments[0])
  const byParent = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { parent_id: rootComments[0].id },
  });
  typia.assert(byParent);
  const replies = nestedComments.filter(c => c.parent_id === rootComments[0].id);
  TestValidator.equals("parent_id reply count")(replies.length)(byParent.data.length);
  for (const c of byParent.data) {
    TestValidator.equals("parent_id")(rootComments[0].id)(c.parent_id);
  }

  // Step 4d: Filter by created_after (after the very first comment)
  const afterFirst = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_after: getIsoDateDelta(rootComments[0].created_at, 1) },
  });
  typia.assert(afterFirst);
  for (const c of afterFirst.data) {
    TestValidator.predicate("created after filter")(
      new Date(c.created_at).getTime() > new Date(rootComments[0].created_at).getTime(),
    );
  }

  // Step 4e: Filter by created_before (before the last comment)
  const lastIdx = allComments.length - 1;
  const beforeLast = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_before: getIsoDateDelta(allComments[lastIdx].created_at, -1) },
  });
  typia.assert(beforeLast);
  for (const c of beforeLast.data) {
    TestValidator.predicate("created before filter")(
      new Date(c.created_at).getTime() < new Date(allComments[lastIdx].created_at).getTime(),
    );
  }

  // Step 4f: Pagination - limit=2, get multiple pages, ensure all covered/no repeats
  const paged1 = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(paged1);
  TestValidator.equals("pagination page 1")(paged1.pagination.current)(1);
  TestValidator.equals("pagination limit")(paged1.pagination.limit)(2);

  const paged2 = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { limit: 2, page: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("pagination page 2")(paged2.pagination.current)(2);

  // Combine paged comments, check for no overlap and all present
  const pagedIds = new Set([...paged1.data, ...paged2.data].map(c => c.id));
  TestValidator.equals("unique paged ids")(paged1.data.length + paged2.data.length)(pagedIds.size);

  // Step 4g: Nonsensical filter: fake user id (should return empty)
  const emptyByFakeAuthor = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { author_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(emptyByFakeAuthor);
  TestValidator.equals("empty fake author filter")(0)(emptyByFakeAuthor.data.length);

  // Step 4h: Nonsensical filter: date out of range (far future)
  const emptyByFutureDate = await api.functional.bbs.posts.comments.patchByPostid(connection, {
    postId: post.id,
    body: { created_after: "2100-01-01T00:00:00.000Z" },
  });
  typia.assert(emptyByFutureDate);
  TestValidator.equals("empty future date filter")(0)(emptyByFutureDate.data.length);
}

