import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";

/**
 * Validate retrieving a single comment's detailed information by ID, with existence, not-found, and permission scenarios.
 *
 * This test exercises the full lifecycle of comment retrieval:
 *   1. Create a user (will be the comment author)
 *   2. Create a post as context for the comment
 *   3. Add a comment to this post from the user
 *   4. Retrieve that comment by ID with correct post ID — assert all properties are present and match what was created
 *   5. Attempt to retrieve a comment using a non-existent ID or the right ID but wrong post (should get not-found error)
 *   6. (If permissions exist for comments) Try to access the comment as a different user and, if any restrictions apply, verify proper error or allow read if public
 *
 * The test focuses on confirming positive retrieval, strict scoping by both postId/commentId, and correct negative/error handling. All key comment fields (content, user_id, parent_id, timestamps, etc.) are checked. Permission edge cases are considered for completeness.
 */
export async function test_api_bbs_test_get_single_comment_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register a user (author)
  const authorUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: 'StrongP@ssword1',
      bio: RandomGenerator.paragraph()(),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(authorUser);

  // 2. Create a post for the comment
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 3. Add a comment as the author
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // 4. Retrieve the comment by correct postId/commentId
  const retrieved = await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });
  typia.assert(retrieved);
  TestValidator.equals("comment content")(comment.content)(retrieved.content);
  TestValidator.equals("author user id")(comment.user_id)(retrieved.user_id);
  TestValidator.equals("post id")(comment.post_id)(retrieved.post_id);
  TestValidator.equals("parent id")(
    (comment.parent_id ?? null)
  )((retrieved.parent_id ?? null));

  // Expected fields presence
  [
    "id",
    "content",
    "user_id",
    "post_id",
    "created_at",
    "updated_at"
  ].forEach((key) => {
    if (!(key in retrieved)) throw new Error(`${key} missing in comment`);
  });

  // 5. Try non-existent comment ID (should fail)
  await TestValidator.error("comment not found")(() =>
    api.functional.bbs.posts.comments.getByPostidAndId(connection, {
      postId: post.id,
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
  // 6. Permission edge: different user attempts to read (simulate another user)
  const otherUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: 'OtherP@ssword2',
      bio: RandomGenerator.paragraph()(),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(otherUser);
  // Try with same connection — should be public, so expect allowed
  const otherRetrieved = await api.functional.bbs.posts.comments.getByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });
  typia.assert(otherRetrieved);
  TestValidator.equals("public comment accessible")(retrieved.id)(otherRetrieved.id);
}

