 * 4. Try to submit a comment with empty content (expect validation error).
 * 5. Try to comment on a random/invalid postId (expect not-found error).
 * 6. Log out, then try to comment (expect auth/permissions error).
 */
export async function test_api_bbs_test_create_comment_on_post_valid_and_invalid(
  connection: api.IConnection,
) {
  // 1. Register a user and note credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassw0rd!";
  const role_id = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email,
      password,
      role_id,
      bio: RandomGenerator.paragraph()(1),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post as this user
  // (Assume connection receives auth token after registration)
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.paragraph()(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

