  const commentContent = RandomGenerator.paragraph()(1);
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: commentContent,
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment content")(commentContent)(comment.content);
  TestValidator.equals("post id matches")(post.id)(comment.post_id);
  TestValidator.equals("user id matches")(user.id)(comment.user_id);
  TestValidator.equals("top-level comment")(
    comment.parent_id ?? null,
  )(null);

  // 4. Try to submit a comment with empty content
  await TestValidator.error("empty content should fail")(() =>
    api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: post.id,
      body: {
        content: "",
      } satisfies bbsComments.ICreate,
    })
  );

  // 5. Try to comment on a random/invalid postId
  const unknownPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("comment on non-existent post should fail")(() =>
    api.functional.bbs.posts.comments.postByPostid(connection, {
      postId: unknownPostId,
      body: {
        content: RandomGenerator.paragraph()(1),
      } satisfies bbsComments.ICreate,
    })
  );

  // 6. Log out, then try to comment (simulate unauthenticated call)
  // For simulation, back up/remove connection.headers.Authorization
  const authBackup = connection.headers?.Authorization;
  if (connection.headers)
    delete connection.headers.Authorization;
  try {
    await TestValidator.error("unauthenticated user cannot comment")(() =>
      api.functional.bbs.posts.comments.postByPostid(connection, {
        postId: post.id,
        body: {
          content: RandomGenerator.paragraph()(1),
        } satisfies bbsComments.ICreate,
      })
    );
  } finally {
    // Restore auth
    if (connection.headers && authBackup)
      connection.headers.Authorization = authBackup;
  }
}

