 * 2. Author creates a post and comments on it.
 * 3. Author updates their own comment: verify content and updated_at.
 * 4. Unauthorized user attempts update: expect permission error.
 * 5. Attempt to update with empty content: expect validation error.
 * 6. Simulate soft-deletion and attempt update: expect error.
 * 7. Attempt to update a non-existent comment: expect error.
 */
export async function test_api_bbs_test_update_comment_content_owner_and_permission(
  connection: api.IConnection,
) {
  // 1. Register two users
  const memberRoleId: string = typia.random<string & tags.Format<"uuid">>();
