import { IConnection, HttpError } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { bbsPosts } from "../../../structures/bbsPosts";
export * as comments from "./comments";

/**
 * Create a new post (BBS: posts table).
 *
 * This API endpoint enables registered users to start a new discussion by
 * submitting a post to the BBS platform. The client must provide all required
 * information: title, body content, associated category, and, implicitly, the
 * user's identity (via authentication).
 *
 * The system records each new post in the 'posts' table and links it to the
 * author's user record and the assigned category. Constraints ensure titles and
 * content are non-empty, with a valid category reference.
 *
 * Upon success, the new post (with its ID and relevant metadata) is immediately
 * available for searching, viewing, and commenting. The operation enforces
 * organization and content standards, returning validation errors if
 * requirements are unmet.
 *
 * Post-creation, users may view, edit, or delete their posts, while moderators
 * can perform additional actions as per role. This endpoint is closely related
 * to GET, PUT, and DELETE operations on posts.
 *
 * @param props.connection
 * @param props.body Information for the new post, including title, content, and
 *   category ID.
 * @path /bbs/posts
