import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { IPageIBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCategories";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 잘못된 페이지네이션 파라미터로 카테고리 목록 요청시 에러 응답 검증
 *
 * 이 테스트는 /bbs/categories PATCH 엔드포인트로 카테고리 목록을 조회할 때,
 * page 또는 limit 파라미터에 잘못된 값(음수, 0, 과도히 큰 숫자 등)을 전달하는 경우
 * API가 반드시 오류 응답을 반환하는지, 그리고 오류 메시지에 어떤 입력이 잘못되었는지 드러나는지 검증합니다.
 *
 * 1. page가 음수인 경우 → "page" 관련 에러
 * 2. page가 0인 경우   → "page" 관련 에러
 * 3. limit이 음수       → "limit" 관련 에러
 * 4. limit이 0          → "limit" 관련 에러
 * 5. limit이 매우 큰 값 → "limit" 관련 에러 또는 business validation
 * 6. contrast로 정상 입력 호출 결과도 검증
 *
 * 각 케이스는 TestValidator.error로 "주어진 잘못된 입력에 대해 오류 발생"을 보장하고,
 * 에러 객체(message 등)에 인풋 파라미터명이 노출되는지까지 적절히 검사합니다.
 *
 * 추가로, 정상 입력(page=1, limit=10)에 대해서는 정상 동작임을 검증함으로 API가 비정상 입력만 차단함을 보장합니다.
 */
export async function test_api_bbs_test_list_categories_with_invalid_pagination_parameters(
  connection: api.IConnection,
) {
  // 1. page가 음수인 경우
  await TestValidator.error("page 음수 오류")(
    async () => {
      await api.functional.bbs.categories.patch(connection, {
        body: { page: -1, limit: 10 } satisfies IBbsCategories.IRequest,
      });
    },
    (error) => {
      // 실제 에러 메시지에 "page"가 노출되는지 검증(있다면 message 문자열에 포함?)
      if (!error?.message?.toLowerCase().includes("page"))
        throw new Error("오류 메시지에 page 정보가 포함되어야 합니다.");
    },
  );

  // 2. page가 0인 경우(일반적으로 page는 1부터...)
  await TestValidator.error("page=0 오류")(
    async () => {
      await api.functional.bbs.categories.patch(connection, {
        body: { page: 0, limit: 10 } satisfies IBbsCategories.IRequest,
      });
    },
    (error) => {
      if (!error?.message?.toLowerCase().includes("page"))
        throw new Error("오류 메시지에 page 정보가 포함되어야 합니다.");
    },
  );

  // 3. limit이 음수
  await TestValidator.error("limit 음수 오류")(
    async () => {
      await api.functional.bbs.categories.patch(connection, {
        body: { page: 1, limit: -100 } satisfies IBbsCategories.IRequest,
      });
    },
    (error) => {
      if (!error?.message?.toLowerCase().includes("limit"))
        throw new Error("오류 메시지에 limit 정보가 포함되어야 합니다.");
    },
  );

  // 4. limit이 0
  await TestValidator.error("limit=0 오류")(
    async () => {
      await api.functional.bbs.categories.patch(connection, {
        body: { page: 1, limit: 0 } satisfies IBbsCategories.IRequest,
      });
    },
    (error) => {
      if (!error?.message?.toLowerCase().includes("limit"))
        throw new Error("오류 메시지에 limit 정보가 포함되어야 합니다.");
    },
  );

  // 5. limit이 과도하게 큰 값
  await TestValidator.error("limit 과대 오류")(
    async () => {
      await api.functional.bbs.categories.patch(connection, {
        body: { page: 1, limit: 1000000 } satisfies IBbsCategories.IRequest,
      });
    },
    (error) => {
      if (!error?.message?.toLowerCase().includes("limit"))
        throw new Error("오류 메시지에 limit 정보가 포함되어야 합니다.");
    },
  );

  // 6. contrast로 정상 입력 호출하여 정상 데이터 반환되는지 확인
  const output = await api.functional.bbs.categories.patch(connection, {
    body: { page: 1, limit: 10 } satisfies IBbsCategories.IRequest,
  });
  typia.assert(output);
  // 정상 케이스: 페이징 정보 타입 일치
  if (
    typeof output !== "object" ||
    !output.pagination ||
    typeof output.pagination.current !== "number" ||
    !Array.isArray(output.data)
  ) {
    throw new Error("정상 입력에 대한 반환 타입 또는 구조가 올바르지 않습니다.");
  }
}

