/**
 * Get a single category's details by ID (categories table).
 *
 * This endpoint fetches the name, description, and creation date for a specific
 * discussion category. The input is the category's UUID. Used by clients or
 * admins to display detailed category information (such as when viewing the
 * category page or offering category selection in post creation). Does not
 * return post data itself, only the category metadata as defined in the
 * categories Prisma schema. Handles invalid/missing category gracefully. No
 * relationships are exposed, only direct metadata. Authorization is open by
 * default but may enforce further checks for admin/management views. Used in
 * category navigation, post composition, or audit reporting. Audit trail
 * (created_at) is returned for management.
 *
 * @param props.connection
 * @param props.id Target category's UUID
 * @path /bbs/categories/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function getById(
  connection: IConnection,
  props: getById.Props,
): Promise<getById.Response> {
  return !!connection.simulate
    ? getById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...getById.METADATA,
          path: getById.path(props),
          status: null,
        },
      );
}
export namespace getById {
  export type Props = {
    /** Target category's UUID */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IBbsCategories;

  export const METADATA = {
    method: "GET",
    path: "/bbs/categories/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/categories/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsCategories =>
    typia.random<IBbsCategories>(g);
  export const simulate = (
    connection: IConnection,
    props: getById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: getById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
