import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";

/**
 * Validates the creation of a new discussion board category by an authenticated administrator.
 *
 * Business context:
 * Administrators can create new categories to organize topics and better structure user posts and navigation. Categories require unique names and nonempty descriptions. Category creation is fundamental for maintaining BBS hierarchy and improving discoverability.
 *
 * Test Process:
 * 1. Prepare a unique category name and a non-empty description.
 * 2. Call the create category API as an authenticated admin.
 * 3. Assert that the creation returns a valid category object with the input values, an auto-generated unique ID (uuid), and a creation timestamp.
 * 4. Optionally, (if category listing API were available) verify the new category appears in listings.
 */
export async function test_api_bbs_test_create_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare unique category data.
  const categoryName = `TestCategory_${RandomGenerator.alphaNumeric(8)}`;
  const categoryDescription = `E2E Created Category for integration testing at ${new Date().toISOString()}`;

  // 2. Call API to create the new category
  const output = await api.functional.bbs.categories.post(
    connection,
    {
      body: {
        name: categoryName,
        description: categoryDescription,
      } satisfies bbsCategories.ICreate,
    },
  );
  typia.assert(output);

  // 3. Validate the response is correct
  TestValidator.equals("category name")(categoryName)(output.name);
  TestValidator.equals("category description")(categoryDescription)(output.description);
  TestValidator.predicate("category id is uuid")(
    typeof output.id === "string" &&
      output.id.match(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i,
      ) !== null,
  );
  TestValidator.predicate("created_at is ISO 8601")(
    typeof output.created_at === "string" &&
      !isNaN(Date.parse(output.created_at)),
  );
}

