/**
 * Validate that updating a category with empty required fields fails input validation.
 *
 * This test ensures that the API enforces non-empty constraints for the `name` and `description` fields when updating a discussion category. If an administrator attempts to update a category by sending empty strings for these fields, the request should be rejected by server-side validation, and an error response should be returned.
 *
 * Business rationale:
 * Categories are used for post organization. Allowing empty names or descriptions undermines clarity and navigation within the discussion board. Validation rules must prevent blank values for these required fields.
 *
 * Test Steps:
 * 1. Create a valid category (dependency) to obtain a category `id` for update attempts.
 * 2. Attempt to update the category by setting `name` to an empty string, expecting input validation failure.
 * 3. Attempt to update the category by setting `description` to an empty string, expecting input validation failure.
 * 4. Attempt to update the category by setting both `name` and `description` to empty strings, expecting input validation failure.
 * 5. Optionally, verify the stored category has not been modified after failed update attempts.
 */
export async function test_api_bbs_test_update_category_with_empty_fields(
  connection: api.IConnection,
) {
  // Step 1: Create a valid category to test update attempts
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: "Test Category - Empty Fields",
      description: "Initial category to verify empty field update handling."
    } satisfies bbsCategories.ICreate
  });
  typia.assert(category);

  // Step 2: Try to update with empty name
  await TestValidator.error("Cannot update with empty name")(() =>
    api.functional.bbs.categories.putById(connection, {
      id: category.id,
      body: {
        name: "",
        description: category.description,
      } satisfies bbsCategories.IUpdate,
    })
  );

  // Step 3: Try to update with empty description
  await TestValidator.error("Cannot update with empty description")(() =>
    api.functional.bbs.categories.putById(connection, {
      id: category.id,
      body: {
        name: category.name,
        description: "",
      } satisfies bbsCategories.IUpdate,
    })
  );

  // Step 4: Try to update with both fields empty
  await TestValidator.error("Cannot update with both fields empty")(() =>
    api.functional.bbs.categories.putById(connection, {
      id: category.id,
      body: {
        name: "",
        description: "",
      } satisfies bbsCategories.IUpdate,
    })
  );

  // Step 5: Optionally, confirm category was not modified by successful get or similar method (not covered here as no GET endpoint was listed)
}

