/**
 * Validate successful deletion of a category without any assigned posts.
 *
 * This test confirms that when an admin deletes a discussion category that has no dependent posts attached to it, the category is actually removed from the system, and its name becomes available for reuse. This verifies the endpoint's happy path for deletion requests, as well as ensuring proper removal logic and name uniqueness enforcement after deletion.
 *
 * Steps:
 * 1. Create a new category (with a unique name and description), ensuring there are no posts under it.
 * 2. Delete the category by its ID using the delete endpoint.
 * 3. Attempt to fetch or operate on the deleted category (if possible) and confirm it no longer exists.
 * 4. Recreate a new category with the same name (to confirm that the name is available for reuse after deletion).
 * 5. Clean-up: Optionally, delete the newly created category for test idempotence.
 */
export async function test_api_bbs_test_delete_category_with_no_dependent_posts(
  connection: api.IConnection,
) {
  // 1. Create a category with a unique name and description
  const uniqueName = `test-cat-${RandomGenerator.alphaNumeric(8)}`;
  const description = RandomGenerator.paragraph()(1);

  const created = await api.functional.bbs.categories.post(connection, {
    body: {
      name: uniqueName,
      description,
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(created);
  TestValidator.equals("category name")(uniqueName)(created.name);

  // 2. Delete the category by its ID
  const deleted = await api.functional.bbs.categories.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(created.id)(deleted.id);
  TestValidator.equals("deleted name")(uniqueName)(deleted.name);

  // 3. Attempt to recreate a new category with the same name
  const recreated = await api.functional.bbs.categories.post(connection, {
    body: {
      name: uniqueName,
      description: RandomGenerator.paragraph()(1),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(recreated);
  TestValidator.equals("reused category name")(uniqueName)(recreated.name);

  // 4. Clean-up: Delete the recreated category for idempotence
  await api.functional.bbs.categories.eraseById(connection, {
    id: recreated.id,
  });
}

