/**
 * Test deletion of a BBS category that is referenced by existing posts.
 *
 * This test validates that the system prevents deletion of categories which still have dependent posts referencing them. The API should enforce referential integrity and not allow removal of referenced categories, returning a conflict or dependency error that requires manual handling.
 *
 * Test workflow:
 * 1. Create a new category as an administrator (ensuring unique name/description).
 * 2. Create a new user account (regular, non-admin) to author a post.
 * 3. Create a new post by the user, explicitly assigning the post to the test category.
 * 4. Attempt to delete the newly created category while it's still referenced by the created post.
 * 5. Assert that the API call fails with a conflict or dependency error (e.g., 409 Conflict or a documented error code), confirming the category cannot be deleted while it is in use.
 *
 * This ensures administrators must reassign or handle dependent posts before category cleanup, enforcing business logic and preventing orphan records.
 */
export async function test_api_bbs_test_delete_category_with_dependent_posts(connection: api.IConnection) {
