import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing user roles with search and pagination.
 *
 * This test ensures the user role listing endpoint supports admin workflows requiring:
 * - Creation of several roles (for search & filter testing)
 * - Paginated search with partial name & description filters
 * - Response includes only matching user roles and correct pagination/total counts
 * - No user data, only role metadata in the response
 *
 * Workflow:
 * 1. Create at least 5 user roles with unique names and descriptions (to enable search diversity).
 * 2. Send a paginated search request with a partial filter for name/description.
 * 3. Verify the response contains only roles matching the filter (every role returned contains the filter in name or description).
 * 4. Verify the response respects pagination (limit, current page, total count, total pages).
 * 5. Ensure response contains only IBbsUserRoles metadata; never user data.
 */
export async function test_api_bbs_test_list_user_roles_with_valid_pagination_and_search(connection: api.IConnection) {
  // 1. Create at least 5 user roles
  const roles: IBbsUserRoles[] = [];
  for (let i = 0; i < 5; i++) {
    const name = `Role_${RandomGenerator.alphabets(5)}_${i}`;
    const description = `This is description ${RandomGenerator.paragraph()()} for role ${i}`;
    const role = await api.functional.bbs.userRoles.post(connection, {
      body: { name, description } satisfies IBbsUserRoles.ICreate,
    });
    typia.assert(role);
    roles.push(role);
  }

  // 2. Choose filter substrings that should only match one or two roles
  const targetRole = roles[2];
  const nameFilter = targetRole.name.slice(0, 6); // partial
  const descriptionFilter = targetRole.description.split(" ")[2]; // grab a word from desc

  // 3. Paginated search by name (limit 2, should find at least one)
  const page1 = await api.functional.bbs.userRoles.patch(connection, {
    body: { page: 1, limit: 2, name: nameFilter } satisfies IBbsUserRoles.IRequest,
  });
  typia.assert(page1);
  // Every role must match partial name
  for (const role of page1.data) {
    TestValidator.predicate(`Role name contains filter: ${nameFilter}`)(role.name.includes(nameFilter));
  }
  TestValidator.equals("page size")(page1.data.length)(Math.min(page1.pagination.limit, page1.pagination.records));

  // 4. Paginated search by description
  const pageByDesc = await api.functional.bbs.userRoles.patch(connection, {
    body: { page: 1, limit: 5, description: descriptionFilter } satisfies IBbsUserRoles.IRequest,
  });
  typia.assert(pageByDesc);
  for (const role of pageByDesc.data) {
    TestValidator.predicate(`Role description contains filter: ${descriptionFilter}`)(role.description.includes(descriptionFilter));
  }

  // 5. Validate pagination & counts
  TestValidator.equals("pagination current page")(1)(page1.pagination.current);
