import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate retrieval of user role details by valid role UUID.
 *
 * This test checks that a user role can be accurately retrieved given its UUID. The purpose is to confirm that the returned role metadata matches exactly what was created, with no extraneous or user-related information included.
 *
 * Steps:
 * 1. Create a new user role using the creation API (unique name and description).
 * 2. Fetch the role by the returned UUID using the GET endpoint.
 * 3. Assert that the name, description, and id in the response match what was created.
 * 4. Check that only the expected metadata fields are present (name, description, id) and no unrelated info (such as user assignments) is included.
 */
export async function test_api_bbs_userRoles_getById(
  connection: api.IConnection,
) {
  // 1. Create a new user role
  const createInput: IBbsUserRoles.ICreate = {
    name: `role_${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(),
  };
  const created: IBbsUserRoles = await api.functional.bbs.userRoles.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Retrieve the role by its UUID
  const fetched: IBbsUserRoles = await api.functional.bbs.userRoles.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // 3. Validate that the returned data matches the creation
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("name")(createInput.name)(fetched.name);
  TestValidator.equals("description")(createInput.description)(fetched.description);

  // 4. Check that no user info or extraneous fields are present
  const allowedKeys = ["id", "name", "description"];
  const actualKeys = Object.keys(fetched);
  for (const key of actualKeys) {
    if (!allowedKeys.includes(key)) {
      throw new Error(`Unexpected property in user role: ${key}`);
    }
  }
}

