  connection: api.IConnection,
) {
  // 1. Try retrieving a user role by an invalid (non-UUID) ID.
  await TestValidator.error("invalid UUID triggers validation error")(() =>
    api.functional.bbs.userRoles.getById(connection, {
      // Intentionally malformed UUID
      id: "not-a-uuid" as any,
    }),
  );

  // 2. Try retrieving a user role by a syntactically valid but non-existent UUID
  const nonExistentId = "0bdf1cfd-0682-47fc-8bc1-fc847b096999"; // unlikely to exist
  await TestValidator.error("non-existent role triggers not-found error")(() =>
    api.functional.bbs.userRoles.getById(connection, {
