  const roleName = `role_${RandomGenerator.alphaNumeric(8)}`; // ensure uniqueness
  const roleDescription = `Test role for capability validation. ${RandomGenerator.paragraph()(2)}`;

  // 2. Call role creation endpoint
  const createdRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
