import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate duplicate user role name error handling.
 *
 * This test ensures that the API enforces uniqueness for user role names. It first creates a user role, then attempts to create another role with the same name. The second attempt must fail, verifying that duplicate names are not accepted.
 *
 * Business context and necessity:
 * Enforcing unique role names prevents confusion and preserves business governance, ensuring that permissions and authorities do not overlap or cause security ambiguities. This validation is critical in admin and configuration workflows where role naming integrity is vital.
 *
 * Step-by-step process:
 * 1. Create a user role with a unique, randomly generated name and description.
 * 2. Attempt to create a second user role using the same name but a different description.
 * 3. The API should respond with a conflict or validation error for the second attempt, signaling a uniqueness constraint violation.
 * 4. Assert that the first creation succeeds, and validate that the second call throws the expected error.
 */
export async function test_api_bbs_test_create_user_role_with_duplicate_name(
  connection: api.IConnection,
) {
  // 1. Create a user role with a unique name.
  const uniqueName = RandomGenerator.alphabets(12);
  const description1 = RandomGenerator.paragraph()();
  const firstRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: uniqueName,
      description: description1,
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(firstRole);
  TestValidator.equals("role name should match")(uniqueName)(firstRole.name);

  // 2. Attempt to create another role with the same name (should fail)
  const description2 = RandomGenerator.paragraph()();
  await TestValidator.error("duplicate role name should be rejected")(
    () =>
      api.functional.bbs.userRoles.post(connection, {
        body: {
          name: uniqueName,
          description: description2,
        } satisfies IBbsUserRoles.ICreate,
      })
  );
}

