/**
 * Validate user role creation with invalid payloads.
 *
 * This function tests the API's ability to handle erroneous user role creation attempts by sending payloads that violate validation/business rules.
 * The test covers scenarios where required fields are missing from the payload, where fields contain empty strings, and where formats are invalid.
 * No user role should ever be created under failure conditions.
 *
 * 1. Attempt to create a role with missing 'name' field (should fail with validation error).
 * 2. Attempt to create a role with missing 'description' field (should fail with validation error).
 * 3. Attempt to create role with both fields present but as empty strings (should fail with validation error).
 * 4. Attempt to create a role with extra undefined properties (should fail, schema should reject extra fields).
 * 5. (If supported) Attempt to create with invalid types (e.g., numbers instead of strings) [but skip if would be a TS compile error].
 * 6. After all failures, list all roles and ensure none of the rejected roles have been created (partial/incomplete creation is not allowed).
 */
export async function test_api_bbs_test_create_user_role_with_invalid_payload(connection: api.IConnection) {
  // 1. Missing 'name' field
  await TestValidator.error("missing 'name' fails")(async () => {
    await api.functional.bbs.userRoles.post(connection, {
      body: {
        // name: missing
        description: "Description present"
      } as any // purposely triggering runtime error, NOT for compile-time omission
    });
  });

  // 2. Missing 'description' field
  await TestValidator.error("missing 'description' fails")(async () => {
    await api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "RoleName"
        // description: missing
      } as any
    });
  });

  // 3. Empty string fields
  await TestValidator.error("empty strings fail")(async () => {
    await api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "",
        description: ""
      }
    });
  });

  // 4. Extra properties
  await TestValidator.error("extra property fails")(async () => {
    await api.functional.bbs.userRoles.post(connection, {
      body: {
        name: "someName",
        description: "someDesc",
        extra: "should not be allowed"
      } as any
    });
  });
  // After all, no invalid record created (would need listing/DB check if such API exists).
}

