import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate updating a user role's name and description via the PUT endpoint.
 *
 * Business context:
 * User roles in the system define access and governance; editing role metadata impacts permissions and onboarding flows. Updating must not break unique name constraints or system integrity.
 *
 * Steps:
 * 1. Create (POST) a user role with a unique name and description.
 * 2. Update (PUT) that role's name and description with new, also-unique values.
 * 3. Confirm the API returns updated information matching the new values.
 * 4. Retrieve a list of roles or the specific role to confirm changes persist.
 * 5. (Negative) Attempt to update the role with a duplicate name—expect a validation/business error response.
 *
 * All changes must obey name uniqueness and proper field validation.
 */
export async function test_api_bbs_userRoles_test_update_user_role_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create original role
  const originalName = RandomGenerator.alphaNumeric(10);
  const originalDescription = RandomGenerator.paragraph()(2);
  const createResp = await api.functional.bbs.userRoles.post(connection, {
    body: { name: originalName, description: originalDescription },
  });
  typia.assert(createResp);
  TestValidator.equals("original name")(originalName)(createResp.name);
  TestValidator.equals("original description")(originalDescription)(createResp.description);

  // 2. Update name and description to new unique values
  const updatedName = RandomGenerator.alphaNumeric(12);
  const updatedDescription = RandomGenerator.paragraph()(3);
  const updateResp = await api.functional.bbs.userRoles.putById(connection, {
    id: createResp.id,
    body: { name: updatedName, description: updatedDescription },
  });
  typia.assert(updateResp);
  TestValidator.equals("updated name")(updatedName)(updateResp.name);
  TestValidator.equals("updated description")(updatedDescription)(updateResp.description);

  // 3. (Re-fetch) Confirm the update is persisted by directly updating again with only description
  const newDesc = RandomGenerator.paragraph()(1);
  const refetchResp = await api.functional.bbs.userRoles.putById(connection, {
    id: createResp.id,
    body: { description: newDesc },
  });
  typia.assert(refetchResp);
  TestValidator.equals("persisted name after description update")(updatedName)(refetchResp.name);
  TestValidator.equals("latest description")(newDesc)(refetchResp.description);

  // 4. (Negative) Attempt duplicate: create a second role, then try to update original to that duplicate name
  const dupName = RandomGenerator.alphaNumeric(16);
  const dupRole = await api.functional.bbs.userRoles.post(connection, {
    body: { name: dupName, description: RandomGenerator.paragraph()(1) },
  });
  typia.assert(dupRole);
  await TestValidator.error("duplicate name forbidden")(async () => {
    await api.functional.bbs.userRoles.putById(connection, {
      id: createResp.id,
      body: { name: dupName },
    });
  });
}

