/**
 * Validate error when updating a user role to a duplicate name.
 *
 * This test verifies that the system enforces unique role names and properly prevents updates that would violate uniqueness constraints. It ensures the backend blocks attempts to assign a user role name that already exists for another role.
 *
 * Step-by-step process:
 * 1. Create the first user role (roleA) with a unique name.
 * 2. Create a second user role (roleB) with a different unique name.
 * 3. Attempt to update the second role, changing its name to match the first role's name (roleA's name).
 * 4. Confirm that the update fails with a uniqueness violation error.
 */
export async function test_api_bbs_test_update_user_role_with_duplicate_name(connection: api.IConnection) {
  // 1. Create the first user role (roleA) with a unique name.
  const roleAName = `roleA_${RandomGenerator.alphabets(8)}`;
  const roleADesc = `Description A ${RandomGenerator.paragraph()(5)}`;
  const roleA = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: roleAName,
      description: roleADesc,
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(roleA);
  // 2. Create a second user role (roleB) with a different unique name.
  const roleBName = `roleB_${RandomGenerator.alphabets(8)}`;
  const roleBDesc = `Description B ${RandomGenerator.paragraph()(5)}`;
  const roleB = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: roleBName,
      description: roleBDesc,
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(roleB);
  // 3. Attempt to update roleB to use roleA's name (should fail).
  await TestValidator.error("duplicate name update should fail")(async () => {
    await api.functional.bbs.userRoles.putById(connection, {
      id: roleB.id,
      body: { name: roleAName } satisfies IBbsUserRoles.IUpdate,
    });
  });
}

