    { name: null, description: roleInput.description },               // d. name null
    { name: roleInput.name, description: null },                      // d. description null
    // e. improper types: numbers or arrays (via type safety, but if allowed)
    // These are TypeScript errors so should not be tested in e2e.
  ];

  for (const body of invalidInputs) {
