    });

    // Confirm record is unchanged (using known data)
    const latest = await getRole();
    TestValidator.equals("name unchanged after failed update")(roleInput.name)(latest.name);
    TestValidator.equals("description unchanged after failed update")(roleInput.description)(latest.description);
