import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate authorization enforcement when updating user roles.
 *
 * This test confirms that updating a user role (by ID) is strictly limited to users with sufficient privileges (e.g., administrators).
 * The scenario ensures that attempts to update a user role by unauthenticated or insufficiently privileged users are rejected by the system with a permission error.
 *
 * 1. Create a user role for testing purposes (requires authorized access).
 * 2. Attempt to update the role as an unauthenticated user (or with an unauthorized connection).
 * 3. Expect the operation to fail (permission denied, not authorized error).
 */
export async function test_api_bbs_test_update_user_role_requires_authorization(connection: api.IConnection) {
  // 1. Create a user role as a privileged user (setup, assume this connection is authorized for creation)
  const createdRole = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: `test_${RandomGenerator.alphaNumeric(8)}`,
      description: "Role created for authorization enforcement testing."
    } satisfies IBbsUserRoles.ICreate
  });
  typia.assert(createdRole);

  // 2. Construct a new connection object WITHOUT authentication (i.e., no authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;

  // 3. Attempt to update the user role with unauthorized/unauthenticated connection
  await TestValidator.error("Update without sufficient authorization must fail")(
    async () => {
      await api.functional.bbs.userRoles.putById(unauthConnection, {
        id: createdRole.id,
        body: {
          name: `unauth_update_${RandomGenerator.alphaNumeric(8)}`,
          description: "Attempted unauthorized update."
        } satisfies IBbsUserRoles.IUpdate
      });
    }
  );
}

