 *
 * Allows system administrators to deactivate a role in the user_roles table. In
 * practice, this might mean preventing new users from being assigned this role,
 * but the role metadata remains for audit and traceability. The endpoint does
 * not physically remove the record. Input is the role's UUID. Can be combined
 * with user management endpoints for full administrative functionality.
 * Authorization and permissions are strictly enforced. Responses document the
 * now-inactive/deleted state. Error handling includes referencing non-existent
 * or protected roles. Audit/meta info is retained.
 *
 * @param props.connection
 * @param props.id Target role's UUID
 * @path /bbs/userRoles/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function eraseById(
  connection: IConnection,
  props: eraseById.Props,
): Promise<eraseById.Response> {
  return !!connection.simulate
    ? eraseById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...eraseById.METADATA,
          path: eraseById.path(props),
          status: null,
        },
      );
}
export namespace eraseById {
  export type Props = {
    /** Target role's UUID */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IBbsUserRoles;

  export const METADATA = {
    method: "DELETE",
    path: "/bbs/userRoles/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/userRoles/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsUserRoles =>
    typia.random<IBbsUserRoles>(g);
  export const simulate = (
    connection: IConnection,
    props: eraseById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: eraseById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
