/**
 * Validate deletion of a user role with invalid or non-existent ID.
 *
 * Ensures that attempting to delete a user role using a malformed or non-existent UUID correctly results in either a validation or not-found error, and does not affect other roles in the system.
 *
 * Steps:
 * 1. Attempt to delete with a malformed ID (not a valid UUID format) and expect a validation error.
 * 2. Attempt to delete with a valid UUID format that does not correspond to any user role, and expect a not-found error.
 * 3. Confirm, if possible, that existing user roles are unaffected (i.e., no unrelated deletions occurred).
 */
export async function test_api_bbs_userRoles_eraseById_test_delete_user_role_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. Attempt to delete with a malformed ID (should yield a validation error)
  await TestValidator.error("malformed ID validation error")(() =>
    api.functional.bbs.userRoles.eraseById(connection, {
      id: "not-a-uuid" as string & tags.Format<"uuid">,
    }),
  );

  // 2. Attempt to delete with a valid UUID that does not exist (should yield a not found error)
  const randomNonexistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent ID not found error")(() =>
    api.functional.bbs.userRoles.eraseById(connection, {
      id: randomNonexistentId,
    }),
  );

  // 3. (Optional) Confirm that no records were deleted inadvertently (could fetch role list if API supports)
  // Not implemented as there is no listing function exposed here.
}

