import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that deleting a user role requires proper authorization and privileges.
 *
 * This test focuses on scenarios where an unauthenticated or unauthorized user attempts to delete a user role. According to business rules, deletion should not be possible unless the caller is appropriately authenticated and has the necessary role (e.g., administrator). The API should respond with an authorization error in these cases.
 *
 * Steps:
 * 1. Create a new user role (requires privileged authentication, assumed handled upstream or via endpoint dependency).
 * 2. Attempt to delete the newly created role without authentication—this should result in an authorization failure (error thrown).
 * 3. (If technically supported) Attempt to delete the same role while authenticated as a normal user/account without delete privileges. This should also fail with an authorization error.
 * 4. (Not tested here) Deletion by admin/privileged user is out of scope for this negative scenario but should be tested in corresponding admin tests.
 *
 * The test must assert that the API correctly enforces authorization and security policies and that unauthorized and unauthenticated attempts fail as expected. The error code/message returned should indicate forbidden access, not a missing resource or other failure reason.
 */
export async function test_api_bbs_test_delete_user_role_requires_authorization(
  connection: api.IConnection,
) {
  // 1. Create a new user role for the test (using provided privileged connection/token)
  const role = await api.functional.bbs.userRoles.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    } satisfies IBbsUserRoles.ICreate,
  });
  typia.assert(role);

  // 2. Attempt to delete the role with NO authentication (e.g., wiped token)
  const unauthenticatedConnection = { ...connection, headers: {} };
  await TestValidator.error("delete forbidden when unauthenticated")(async () => {
    await api.functional.bbs.userRoles.eraseById(unauthenticatedConnection, { id: role.id });
  });

  // 3. (If the environment supports) Attempt to delete as an unauthorized/non-admin user.
  // This requires ability to create/login as a regular user, which is not specified here, so is commented out/pseudocoded.
  // const userConnection = await getNonPrivilegedConnection();
  // await TestValidator.error('delete forbidden for unauthorized user')(async () => {
  //   await api.functional.bbs.userRoles.eraseById(userConnection, { id: role.id });
  // });
}

