import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";
import type { IPageIBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing votes with advanced filters and pagination as an administrator.
 *
 * This test validates that an administrator can query votes with advanced filters (by
 * user, target type, and value) and pagination—as per business/analytics scenarios. It ensures
 * results are accurate, paginated, and that only privileged users can perform this search.
 *
 * Workflow:
 * 1. Register several normal users and an admin account (with distinct role_id for admin).
 * 2. Have users create posts.
 * 3. Have users add comments to posts.
 * 4. Cast a variety of votes on both posts and comments, from different users (upvotes, downvotes).
 * 5. Log in as the admin to use /bbs/votes PATCH endpoint.
 * 6. Test listing all votes (no filters), and with various filters:
 *    - Filter by a specific voter user_id
 *    - Filter by post_id vs comment_id
 *    - Filter by value (+1, -1)
 *    - Pagination: check that returning pages divides correctly by limit, does not crash if paginating past last page
 *    - Edge case: filter that results in zero matches; invalid filter params
 * 7. Validate each response for data correctness, pagination info, and error conditions.
 */
export async function test_api_bbs_test_list_votes_with_filter_and_pagination_as_admin(
  connection: api.IConnection,
) {
  // 1. Register roles: simulate some UUIDs for roles or select random UUID for admin/normal role
  const adminRoleId = typia.random<string & tags.Format<"uuid">>();
  const userRoleId = typia.random<string & tags.Format<"uuid">>();

  // 2. Register users (Admin + 2 Users)
  const adminReg = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Admin123!@#",
      role_id: adminRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(adminReg);

  const user1 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "User1pass!",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user1);

  const user2 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "User2pass!",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user2);

  // 3. Create posts by users
  const post1 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post1);

  const post2 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(2),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post2);

  // 4. Add comments to each post
  const comment1 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post1.id,
    body: {
      content: "First comment on post 1",
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment1);

  const comment2 = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post2.id,
    body: {
      content: "First comment on post 2",
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment2);

  // 5. Cast a variety of votes
  // Votes on posts
  const vote1 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post1.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote1);

  const vote2 = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post2.id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote2);

  // Votes on comments
  const vote3 = await api.functional.bbs.votes.post(connection, {
    body: {
      comment_id: comment1.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote3);

  const vote4 = await api.functional.bbs.votes.post(connection, {
    body: {
      comment_id: comment2.id,
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote4);

  // 6. As admin, query votes with no filters (get all)
  const allVotesRes = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(allVotesRes);
  TestValidator.predicate("Returns >= 4 votes at setup")(allVotesRes.data.length >= 4);

  // 7. Filter by voter (adminReg.id)
  const byAdminVotes = await api.functional.bbs.votes.patch(connection, {
    body: {
      user_id: adminReg.id,
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(byAdminVotes);
  TestValidator.equals("All results have user_id = adminReg.id")(
    true,
  )(
    byAdminVotes.data.every((row) => row.user_id === adminReg.id)
  );

  // 8. Filter by post_id
  const byPost1Votes = await api.functional.bbs.votes.patch(connection, {
    body: {
      post_id: post1.id,
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(byPost1Votes);
  TestValidator.equals("All results are for post1.id")(
    true,
  )(byPost1Votes.data.every((row) => row.post_id === post1.id));

  // 9. Filter by comment_id
  const byComment2Votes = await api.functional.bbs.votes.patch(connection, {
    body: {
      comment_id: comment2.id,
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(byComment2Votes);
  TestValidator.equals("All results are for comment2.id")(
    true,
  )(byComment2Votes.data.every((row) => row.comment_id === comment2.id));

  // 10. Filter by value (+1)
  const byValueUp = await api.functional.bbs.votes.patch(connection, {
    body: {
      value: 1,
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(byValueUp);
  TestValidator.equals("All values == 1")(
    true,
  )(byValueUp.data.every((row) => row.value === 1));

  // 11. Pagination: set limit = 2, get page 1 and 2
  const pagedResult1 = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(pagedResult1);
  TestValidator.equals("Page 1 size")(
    2
  )(pagedResult1.data.length);

  const pagedResult2 = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: 2,
      limit: 2,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(pagedResult2);
  TestValidator.predicate("Page 2 size >= 0 and <= 2")(
    pagedResult2.data.length >= 0 && pagedResult2.data.length <= 2
  );

  // 12. Edge: zero-matching results
  const noneMatchRes = await api.functional.bbs.votes.patch(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IBbsVote.IRequest,
  });
  typia.assert(noneMatchRes);
  TestValidator.equals("Zero results for nonexistent user")(
    0
  )(noneMatchRes.data.length);
  TestValidator.predicate("Pagination still valid")(
    noneMatchRes.pagination.current === 1 &&
    noneMatchRes.pagination.records === 0 &&
    Array.isArray(noneMatchRes.data)
  );

  // 13. Edge: paginating past last page
  const totalPages = Math.max(
    1,
    Math.ceil(allVotesRes.pagination.records / allVotesRes.pagination.limit),
  );
  const pastLastPage = await api.functional.bbs.votes.patch(connection, {
    body: {
      page: totalPages + 2,
      limit: allVotesRes.pagination.limit,
    } satisfies IBbsVote.IRequest,
  });
