import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate retrieval of a single vote's details as both the voter and a privileged moderator/admin.
 *
 * This test ensures that a vote record can be properly fetched by the user who created it, as well as by a moderator/admin, and that no inappropriate sensitive data is leaked to unauthorized users.
 *
 * Steps:
 * 1. Create two user accounts: one standard user (the 'owner' of the vote) and one moderator/admin user (with privileged role).
 * 2. Authenticate as the standard user (owner) and create a new post (to vote on).
 * 3. While authenticated as the owner, cast either an upvote (+1) or downvote (-1) for the created post. Capture the vote's ID.
 * 4. Retrieve the vote by its ID as the owner; verify all relevant vote details are returned and belong to the correct user, and check that only permitted fields are present.
 * 5. Authenticate as the moderator/admin user.
 * 6. Retrieve the same vote by its ID as the privileged user; verify that moderator can see expected details, but still cannot see other users' full voting history or any overly sensitive data not permitted to their role.
 * 7. Assert that in both cases, the vote record returned contains the correct IDs, value, and target, and does not leak other users' voting data.
 */
export async function test_api_bbs_test_get_vote_detail_as_owner_and_moderator(connection: api.IConnection) {
  // 1. Create user accounts: owner (standard user) and moderator/admin.
  const ownerRoleId = typia.random<string & tags.Format<"uuid">>();
  const moderatorRoleId = typia.random<string & tags.Format<"uuid">>();

  const ownerUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Passw0rd!123",
      role_id: ownerRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(ownerUser);

  const moderatorUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPass!345",
      role_id: moderatorRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(moderatorUser);

  // 2. Authenticate as the owner. (Assume auto-login upon creation or attach session as needed)
  // 3. Owner creates a post.
  const categoryId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1, 3),
      content: RandomGenerator.content()(1)(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Owner casts a vote on the post.
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: RandomGenerator.pick([1, -1]),
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // 5. Retrieve the vote as owner.
  const retrievedAsOwner = await api.functional.bbs.votes.getById(connection, {
    id: vote.id,
  });
  typia.assert(retrievedAsOwner);

  TestValidator.equals("Vote's user_id matches owner user")(ownerUser.id)(retrievedAsOwner.user_id);
  TestValidator.equals("Vote's post_id matches post")(post.id)(retrievedAsOwner.post_id);
  TestValidator.equals("Vote value matches")(vote.value)(retrievedAsOwner.value);

  // 6. Authenticate as moderator/admin.
  // (Simulate credential switch or manual token set if needed)
  // For test, assume connection can be switched to use moderatorUser.
  // ... (application logic for switch, not shown)
  // If system requires, use login endpoint or set header.

  // 7. Retrieve the same vote as moderator/admin.
  const retrievedAsModerator = await api.functional.bbs.votes.getById(connection, {
    id: vote.id,
  });
  typia.assert(retrievedAsModerator);

  TestValidator.equals("Vote's user_id matches owner user")(ownerUser.id)(retrievedAsModerator.user_id);
  TestValidator.equals("Vote's post_id matches post")(post.id)(retrievedAsModerator.post_id);
  TestValidator.equals("Vote value matches")(vote.value)(retrievedAsModerator.value);

  // 8. Ensure no unrelated user voting history is exposed in the response as either role.
  // (If the IBbsVote schema changes to include related user voting arrays, add assertions here)
}

