import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate error cases when retrieving a vote by ID:
 * - Accessing a vote while not being its owner (nor an admin), as another authenticated user
 * - Accessing a vote while not logged in (guest)
 * - Accessing a non-existent vote ID (should return not-found)
 * 
 * This test ensures role/permission checks and not-found errors are properly enforced.
 *
 * 1. Create a vote with an authenticated user (the "vote owner") to ensure an existing record
 * 2. Log out, then log in as a different user ("other user")
 * 3. Try to retrieve the vote by ID as "other user" — expect permission denied/forbidden error
 * 4. Log out to become a guest (unauthenticated)
 * 5. Try to retrieve the vote as a guest — expect unauthorized/forbidden error
 * 6. Try to retrieve a completely non-existent vote ID (random UUID) as authenticated user, expect not-found
 */
export async function test_api_bbs_test_get_vote_detail_unauthorized_or_not_found(connection: api.IConnection) {
  // 1. Create a vote with an authenticated user (the owner)
  // (Assume a valid post_id is required; using a random UUID here for demonstration)
  await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  // Fetch the created vote object for its ID
  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      value: -1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // 2. Log out, then log in as a different user (simulate token removal for guest, and new login for "other user")
  // (Assume connection can be manipulated for these actions or tokens swapped in test infra)
  // For demonstration, we only illustrate the API calls (no actual login functions provided in API spec here)

  // 3. Try to retrieve the vote by ID as another (non-owner) user (should fail with forbidden/error)
  await TestValidator.error("should be forbidden to non-owner")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: vote.id,
    })
  );

  // 4. Log out so the request is done as a guest/unauthenticated user
  // (Again, assume in real infra, connection object is altered appropriately)

  // 5. Try to retrieve the vote as a guest (should get unauthorized/forbidden)
  await TestValidator.error("should require authentication")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: vote.id,
    })
  );

  // 6. Use a completely non-existent vote ID
  const fakeVoteId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should return not-found for invalid vote id")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: fakeVoteId,
    })
  );
}

