import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate error and permission cases for retrieving a vote by ID.
 *
 * This test checks that:
 *  - Accessing a vote as another authenticated user (non-owner) returns a forbidden error
 *  - Accessing a vote as a guest (not logged in) returns unauthorized/forbidden
 *  - Accessing a truly non-existent vote ID returns not-found
 * 
 * Permissions must be enforced so only the vote's owner (or privileged users) can view the record, and proper error codes are used for invalid access.
 *
 * Steps:
 * 1. Create a vote as one authenticated user (the vote owner)
 * 2. Simulate logging in as a different user
 * 3. Attempt to get the vote by ID (should be forbidden)
 * 4. Simulate logging out (unauthenticated/guest)
 * 5. Attempt to get the vote by ID as guest (should fail/forbidden)
 * 6. Attempt to get a vote by a random non-existent UUID (should be not-found)
 */
export async function test_api_bbs_test_get_vote_detail_unauthorized_or_not_found(connection: api.IConnection) {
  // 1. Create a vote as the vote owner
  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // 2. Simulate logging in as a different user
  // In actual test infra, swap the authentication on the connection here
  // For this code, assume connection now points to another (non-owner) user

  // 3. Attempt to get the vote as another (non-owner) user - should fail (permission denied/forbidden)
  await TestValidator.error("forbidden for non-owner")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: vote.id,
    })
  );

  // 4. Simulate logging out for guest/unauthenticated access
  // Again, in real infra the connection would have tokens cleared
  // Here, we assume connection now represents a guest session

  // 5. Attempt to get the vote as a guest/unauthenticated - should fail (unauthorized/forbidden)
  await TestValidator.error("fails for guest user")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: vote.id,
    })
  );

  // 6. Attempt to get a vote by a random UUID - should return not-found
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for random UUID")(() =>
    api.functional.bbs.votes.getById(connection, {
      id: nonExistentId,
    })
  );
}

