import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate successful creation of a vote on an existing post by an authenticated regular user and enforcement of the one-vote-per-user constraint.
 *
 * This test verifies that an authenticated user can create an upvote (+1) or downvote (-1) for a post via the /bbs/votes endpoint, checks the correctness of response, and ensures double voting is prevented.
 *
 * Steps:
 * 1. Register a new user (with member role).
 * 2. Register a post as that user (requires category_id, so simulate as needed).
 * 3. Submit a vote (+1).
 * 4. Validate that the vote is attributed to the correct post and user.
 * 5. Attempt to vote again on the same post (should fail with unique constraint violation or API error).
 */
export async function test_api_bbs_test_create_vote_on_post_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user
  const role_id = typia.random<string & tags.Format<"uuid">>(); // Simulated 'member' role ID
  const userReg = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      role_id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userReg);

  // 2. Register a new post
  const category_id = typia.random<string & tags.Format<"uuid">>(); // Simulate category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Submit an upvote (+1)
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("vote.post_id")(post.id)(vote.post_id);
  TestValidator.equals("vote.user_id")(userReg.id)(vote.user_id);
  TestValidator.equals("vote.value")(1)(vote.value);

  // 4. Attempt to double vote on the same post (should fail)
  await TestValidator.error("double vote forbidden")(() =>
    api.functional.bbs.votes.post(connection, {
      body: {
        post_id: post.id,
        value: 1,
      } satisfies IBbsVote.ICreate,
    })
  );
}

