import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate that duplicate voting by the same user on the same target (post or comment) is rejected by the system.
 *
 * Business case: Users should only be able to cast a single upvote or downvote per post or comment. The system must enforce a one-vote-per-user-per-target (post or comment) policy. Attempting a second vote on the same target should result in a unique constraint violation or business logic error.
 *
 * Test process:
 * 1. Register a new user account.
 * 2. Create a new post to serve as the target for voting.
 * 3. As the registered user, cast the first vote (upvote or downvote) on the post. Expect success.
 * 4. Attempt to cast a second vote (can be the same or opposite value) on the same post by the same user. Expect the request to fail with a unique constraint/business rule error.
 * 5. (Bonus path for comments) - If applicable, perform the above steps for voting on a comment (requires comment API, skip if not available in the provided API spec).
 *
 * Validates both correct behavior (first vote is accepted) and proper error handling (second vote rejected) for post voting. Ensures data integrity for voting feature.
 */
export async function test_api_bbs_test_create_vote_duplicate_on_same_target_fails(connection: api.IConnection) {
  // 1. Register a user
  const testRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongPass!23",
      role_id: testRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post (assume system recognizes currently authenticated user as author)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 3. Cast the first vote (should succeed)
  const firstVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(firstVote);

  // 4. Attempt to cast a second vote by the same user on the same post (should fail)
  await TestValidator.error("Duplicate vote should fail")(() =>
    api.functional.bbs.votes.post(connection, {
      body: {
        post_id: post.id,
        value: 1,
      } satisfies IBbsVote.ICreate,
    })
  );
  // (Comment voting scenario omitted as comment entity is not provided in available API/DTO)
}

