import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validates that unauthenticated users cannot cast votes on posts.
 *
 * Business context:
 * Only authenticated (logged-in) users are permitted to cast upvotes or downvotes on posts. Guest/unauthenticated users must be blocked and receive an authentication error if they attempt to vote.
 *
 * Test Steps:
 * 1. (Dependency) Create a BBS post (requires authentication, handled outside this test).
 * 2. Attempt to create a vote on the post as a guest (connection without authentication/bearer token).
 * 3. Expect the vote creation API to fail with an authentication error (usually 401 Unauthorized/403 Forbidden).
 * 4. Validate that no vote is created for the unauthenticated user or any guest session.
 */
export async function test_api_bbs_test_create_vote_unauthorized_user_fails(connection: api.IConnection) {
  // Step 1: (Dependency) Post creation handled externally—requires a valid post to target with a vote.
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      content: RandomGenerator.content()(2)(),
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // Step 2: Prepare a no-auth connection by omitting the Authorization header.
  const unauthenticatedConnection = { ...connection, headers: { ...connection.headers } };
  if (unauthenticatedConnection.headers) delete unauthenticatedConnection.headers.Authorization;

  // Step 3: Attempt to create a vote as a guest (unauthenticated user).
  await TestValidator.error("Unauthenticated users must not be able to cast votes.")(
    () =>
      api.functional.bbs.votes.post(unauthenticatedConnection, {
        body: {
          post_id: post.id,
          value: 1,
        },
      })
  );
}

