import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate error handling when attempting to create a vote with an invalid or nonexistent target (either post or comment).
 *
 * Business context:
 * In the BBS platform, users can upvote or downvote posts and comments. However, attempting to vote on a non-existent or deleted target (by providing a random or invalid UUID as the post_id or comment_id) should result in a not-found error. This test ensures such error responses are consistently enforced for system integrity and to prevent phantom votes.
 *
 * Step-by-step process:
 * 1. Register a valid user to perform voting actions.
 * 2. Attempt to create a vote for a post, using a random UUID for post_id (no such post exists).
 * 3. Confirm the system returns a not-found error and no vote is created.
 * 4. Repeat the process for comment_id (no such comment exists).
 */
export async function test_api_bbs_test_create_vote_with_invalid_target_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a valid user to perform voting actions
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      role_id: typia.random<string & tags.Format<"uuid">>(),
      // It's fine for bio to be null/omitted
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Attempt to create a vote for a nonexistent post (random UUID for post_id)
  await TestValidator.error("voting on nonexistent post should fail")(
    async () => {
      await api.functional.bbs.votes.post(connection, {
        body: {
          post_id: typia.random<string & tags.Format<"uuid">>(), // assumed to not exist
          comment_id: null,
          value: 1,
        } satisfies IBbsVote.ICreate,
      });
    },
  );

  // 3. Attempt to create a vote for a nonexistent comment (random UUID for comment_id)
  await TestValidator.error("voting on nonexistent comment should fail")(
    async () => {
      await api.functional.bbs.votes.post(connection, {
        body: {
          post_id: null,
          comment_id: typia.random<string & tags.Format<"uuid">>(), // assumed to not exist
          value: -1,
        } satisfies IBbsVote.ICreate,
      });
    },
  );
}

