import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validate that a vote owner can successfully update their vote value (e.g., switch from +1 to -1) and that the update is reflected in the vote record and any related aggregates.
 *
 * Business context:
 * - Only the owner of a vote can update its value.
 * - Vote updates should immediately reflect in aggregate tallies, though the API only returns the vote record.
 *
 * Steps:
 * 1. Create a user (will be the voter).
 * 2. Create a BBS post (will be the vote target).
 * 3. As the created user, cast an upvote (+1) on the post.
 * 4. Update that vote to change its value from +1 to -1.
 * 5. Fetch the updated vote and assert the value has changed to -1.
 * 6. Optionally validate that the vote references are correct and that the user and post IDs are unchanged.
 */
export async function test_api_bbs_test_update_vote_value_successful_as_owner(connection: api.IConnection) {
  // 1. Create a user (voter)
  const user: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(6) + "@example.com",
      password: RandomGenerator.alphaNumeric(10),
      bio: RandomGenerator.alphaNumeric(20),
      // For test, assign a random UUID as role_id (assuming a valid role exists in test db, if not test would need to fetch/create roles first)
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a post as the user
  const post: bbsPosts = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.paragraph()(2),
    },
  });
  typia.assert(post);

  // 3. Cast an upvote (+1) as the user
  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("original vote value")(1)(vote.value);

  // 4. Update the vote to a downvote (-1)
  const updatedVote: IBbsVote = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IBbsVote.IUpdate,
  });
  typia.assert(updatedVote);

  // 5. Validate the vote value changed
  TestValidator.equals("updated vote value")(-1)(updatedVote.value);

  // 6. Validate vote references remain the same
  TestValidator.equals("user_id unchanged")(vote.user_id)(updatedVote.user_id);
  TestValidator.equals("post_id unchanged")(vote.post_id)(updatedVote.post_id);
}

