import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Validates access control enforcement for updating a vote record.
 *
 * This test ensures that only the vote owner and privileged users (e.g., moderator) are allowed to update a given vote record, while all others (e.g., unrelated user, guest) are denied access.
 *
 * Implementation steps:
 *  1. Register three users: the vote owner (regular), a non-privileged user, and a privileged user (moderator).
 *  2. As the owner, create a post to be the vote target.
 *  3. As the owner, create a vote for the post.
 *  4. Try updating the vote as:
 *     a) The owner -> Should succeed.
 *     b) Another (non-privileged) user -> Should fail (permission error).
 *     c) Guest/unauthenticated request -> Should fail (auth error).
 *     d) Privileged user (moderator) -> Should succeed.
 *
 * After each attempt, check permissions are enforced: owner and moderator can update, all others are denied.
 */
export async function test_api_bbs_test_update_vote_as_non_owner_or_unauthorized_fails(connection: api.IConnection) {
  // Step 1. Register roles
  // (Assume we have static role UUIDs for 'member' and 'moderator')
  const member_role_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const moderator_role_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 1.a. Register vote owner (regular user)
  const owner = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      bio: "Vote owner",
      role_id: member_role_id,
    },
  });
  typia.assert(owner);

  // 1.b. Register another user (non-privileged)
  const other = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      role_id: member_role_id,
    },
  });
  typia.assert(other);

  // 1.c. Register moderator
  const moderator = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      role_id: moderator_role_id,
    },
  });
  typia.assert(moderator);

  // Step 2. As owner, create a post
  // (Assume system uses context user from connection/session)
  // Simulate login as owner (if required by the API)
  // (If login API not present, assume api.connection.headers are used to assign identity)
  // Replace with correct way to assign user context as needed.

  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Vote target",
      content: "Post for vote test.",
    },
  });
  typia.assert(post);

  // Step 3. As owner, create a vote for the post
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    },
  });
  typia.assert(vote);

  // Step 4a. Owner attempts to update vote (should succeed)
  const updated_vote = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: { value: -1 },
  });
  typia.assert(updated_vote);
  TestValidator.equals("vote updated by owner")(-1)(updated_vote.value);

  // Step 4b. Non-owner, non-privileged user (should fail)
  // Simulate switching to 'other' user's session
  // Here, this would require re-authentication if an auth API existed; if only the connection is needed, assign headers accordingly
  TestValidator.error("update by unrelated user fails")(async () => {
    await api.functional.bbs.votes.putById(connection, {
      id: vote.id,
      body: { value: 1 },
    });
  });

  // Step 4c. Guest (no authentication) (should fail)
  // Simulate a new connection with no auth header
  TestValidator.error("update by guest fails")(async () => {
    await api.functional.bbs.votes.putById({ ...connection, headers: {} }, {
      id: vote.id,
      body: { value: 1 },
    });
  });

  // Step 4d. Moderator user (should succeed)
  // Simulate switching to moderator session
  const mod_updated_vote = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: { value: 1 },
  });
  typia.assert(mod_updated_vote);
  TestValidator.equals("vote updated by moderator")(1)(mod_updated_vote.value);
}

