/**
 * Validates access control enforcement for updating a vote.
 *
 * Ensures that only the vote owner and privileged users (moderators) may update
 * a vote, while unrelated users and guests are forbidden. Tests permission
 * boundaries by covering the following user roles:
 *  1. Vote owner (should succeed)
 *  2. Unrelated non-privileged user (should fail)
 *  3. Unauthenticated guest (should fail)
 *  4. Moderator (should succeed)
 *
 * Steps:
 *  1. Register and create: (a) an owner, (b) another user, and (c) moderator.
 *     (Assumes static role UUIDs or a defined set for member/moderator roles.)
 *  2. As owner, create a post (vote target) and a vote.
 *  3. Attempt to update the vote as:
 *     a) Owner — must succeed.
 *     b) Other user — must fail (permission error).
 *     c) Guest (no user) — must fail (auth error).
 *     d) Moderator — must succeed.
 *  4. Validate all permission boundaries using assertions.
 */
export async function test_api_bbs_test_update_vote_as_non_owner_or_unauthorized_fails(connection: api.IConnection) {
  // ---- Role UUID setup (replace with actual system UUIDs in real environments) ----
  const member_role_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const moderator_role_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

