  typia.assert(owner);
  const otherUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      role_id: member_role_id,
    },
  });
  typia.assert(otherUser);
  const moderator = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      role_id: moderator_role_id,
    },
  });
  typia.assert(moderator);

  // 2. Owner creates post and vote
  // (Assume session switching or token assignment is handled externally)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Vote target post",
