    },
  });
  typia.assert(post);
  const vote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: 1,
    },
  });
  typia.assert(vote);

  // 3a. Update as owner (should succeed)
  const updatedByOwner = await api.functional.bbs.votes.putById(connection, {
    id: vote.id,
    body: { value: -1 },
  });
  typia.assert(updatedByOwner);
