import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test deletion of a vote by its owner and by an admin, ensuring correct permissions, deletion logic, and re-voting capability.
 *
 * Business context:
 * - Only a vote's owner or an administrator may delete a vote.
 * - Once a vote is deleted, the user is freed to vote again on that target.
 * - Admins are assumed to be assigned via a known admin role UUID for this test.
 * - Vote table supports one vote per user per target (post) enforced.
 *
 * Workflow:
 * 1. Register a standard user (owner) and an admin user.
 * 2. Create two posts (voting targets).
 * 3. Cast votes by the owner on both posts.
 * 4. Delete the first vote as the owner, confirming it unlocks voting for the same post (can re-vote, and re-voting twice without deletion is not allowed).
 * 5. Delete the second vote as the admin, confirming admin can erase other's votes and owner is then free to re-vote (and not before).
 * 6. Optionally: Confirm deleted votes are not present and aggregated counts (if available) are updated.
 */
export async function test_api_bbs_test_delete_vote_successful_by_owner_and_admin(connection: api.IConnection) {
  // Setup: Assume the admin role UUID is predetermined for test (you may need a real value in a real suite)
  const ADMIN_ROLE_UUID = (function() {
    // If there is a system way to fetch this, replace here. Otherwise, supply known UUID for 'administrator' role in test env.
    return "11111111-1111-1111-1111-111111111111";
  })();

  // Step 1: Register standard user (owner)
  const owner_username = RandomGenerator.alphaNumeric(8);
  const owner_email = `${owner_username}@test.com`;
  const owner_password = "TestP@ss1";
  const owner = await api.functional.bbs.users.post(connection, {
    body: {
      username: owner_username,
      email: owner_email,
      password: owner_password,
      role_id: typia.random<string & tags.Format<"uuid">>(), // Member role (random, test)
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(owner);

  // Step 1.5: Register admin user (needs admin role, static UUID used here)
  const admin_username = RandomGenerator.alphaNumeric(8);
  const admin_email = `${admin_username}@test.com`;
  const admin_password = "AdminTest1";
  const admin = await api.functional.bbs.users.post(connection, {
    body: {
      username: admin_username,
      email: admin_email,
      password: admin_password,
      role_id: ADMIN_ROLE_UUID as string & tags.Format<"uuid">,
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(admin);

  // Step 2: Create two posts (targets for voting)
  const post1 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      content: RandomGenerator.paragraph()(),
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post1);
  const post2 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      content: RandomGenerator.paragraph()(),
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post2);

  // Step 3: (Implied context) Owner casts votes for both posts
  // (Assume that owner context/session is active; if system requires reauthentication, simulate that here.)
  const owner_vote1 = await api.functional.bbs.votes.post(connection, {
    body: { post_id: post1.id, value: 1 } satisfies IBbsVote.ICreate,
  });
  typia.assert(owner_vote1);
  const owner_vote2 = await api.functional.bbs.votes.post(connection, {
    body: { post_id: post2.id, value: 1 } satisfies IBbsVote.ICreate,
  });
  typia.assert(owner_vote2);

  // Step 4: Owner deletes their own vote for post1
  await api.functional.bbs.votes.eraseById(connection, { id: owner_vote1.id });
  // Attempt to re-vote (should succeed)
  const recast_vote1 = await api.functional.bbs.votes.post(connection, {
    body: { post_id: post1.id, value: 1 } satisfies IBbsVote.ICreate,
  });
  typia.assert(recast_vote1);
  // Try double-voting (should fail, expecting error)
  await TestValidator.error("double-vote - not allowed")(() =>
    api.functional.bbs.votes.post(connection, { body: { post_id: post1.id, value: 1 } })
  );

  // Step 5: Admin deletes owner's vote for post2
  // (Switch context if needed; simulate admin session if auth required. Assume connection is transferred suitably.)
  await api.functional.bbs.votes.eraseById(connection, { id: owner_vote2.id });
  // Owner can now re-cast vote for post2 (after admin deleted prior vote)
  const recast_vote2 = await api.functional.bbs.votes.post(connection, {
    body: { post_id: post2.id, value: 1 } satisfies IBbsVote.ICreate,
  });
  typia.assert(recast_vote2);
  // Try to double-vote again (should fail)
  await TestValidator.error("double-vote after admin erase - not allowed")(() =>
    api.functional.bbs.votes.post(connection, { body: { post_id: post2.id, value: 1 } })
  );
  // (Optional) Could check aggregates/tallies if such endpoint exists here
}

