import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IBbsVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsVote";

/**
 * Test that a non-owner/non-privileged user cannot delete another user's vote.
 *
 * This test verifies access control and data integrity for vote deletion.
 * We create two users (the owner of the vote and a second user).
 * The owner creates a post, and casts a vote on the post. Then, the second user attempts to delete this vote (which should fail due to access controls). We verify that deletion is forbidden, and that the vote remains after the failed deletion.
 *
 * Steps:
 * 1. Register the vote owner user (userA) with normal role ID.
 * 2. Register another regular user (userB) with normal role ID.
 * 3. UserA logs in, creates a post, and casts a vote (+1 or -1) on it.
 * 4. UserB logs in, attempts to delete userA's vote via DELETE /bbs/votes/{id}.
 * 5. Assert that the API call fails with a proper error (403 Forbidden or similar), and the vote has not been deleted (it is still present).
 *
 * Notes:
 * - If role IDs need to be static/known, use a fixed normal user role for both users.
 * - If there is not a GET for the vote, we can disregard additional read-back and focus on the expected error on deletion attempt.
 */
export async function test_api_bbs_test_delete_vote_as_non_owner_fails(
  connection: api.IConnection,
) {
  // Step 1: Register userA (vote owner) with normal user role ID (static or generated)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userAUsername = RandomGenerator.alphaNumeric(8);
  const userA: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: userAUsername,
      email: userAEmail,
      password: "Password1!@#",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  // Step 2: Register userB (non-owner regular user)
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userBUsername = RandomGenerator.alphaNumeric(8);
  const userB: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: userBUsername,
      email: userBEmail,
      password: "Password1!@#",
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // Step 3: UserA creates a post and casts a vote
  // (Assume implicit login/auth is handled at connection layer)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post: bbsPosts = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(1)(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  const vote: IBbsVote = await api.functional.bbs.votes.post(connection, {
    body: {
      post_id: post.id,
      value: RandomGenerator.pick([1, -1]),
    } satisfies IBbsVote.ICreate,
  });
  typia.assert(vote);

  // Step 4: Switch to userB session/auth
  // (Replace connection headers/auth to use userB; implementation depends on connection/session design)

  // Step 5: UserB attempts to delete userA's vote
  await TestValidator.error("Non-owner userB cannot delete userA's vote")(
    () => api.functional.bbs.votes.eraseById(connection, { id: vote.id }),
  );

  // (Step 6: Optionally, check the vote still exists - depends on available API. Not implemented if no GET)
}

