  // 2. Register userB (second regular user)
  const userB: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password1!@#",
      role_id: userRoleId,
