  });
  typia.assert(userB);

  // 3. UserA creates a post
  const post: bbsPosts = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
