import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that attempting to delete a BBS vote with an invalid or already-deleted ID fails appropriately.
 *
 * This test ensures that the API responds correctly with appropriate errors when a user attempts to delete:
 *  - A vote that does not exist (random/invalid UUID)
 *  - A vote that existed but was already deleted
 *
 * Steps:
 * 1. Register a new user to satisfy dependency requirements.
 * 2. Attempt to delete a vote using an obviously invalid UUID (never existed in the table) and confirm a not-found (or appropriate) error is returned.
 * 3. (OPTIONAL: If needed, simulate creation of a vote, then delete it, then try to delete again to check already-deleted error handling. However, since no vote creation endpoint is available, this step is skipped.)
 * 4. Confirm that appropriate error status or error response is received for all invalid deletion attempts.
 */
export async function test_api_bbs_test_delete_vote_with_invalid_id_fails(connection: api.IConnection) {
  // 1. Register a new user as context for the operation (even if not strictly needed for errors)
  const fakeUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphabets(6) + "@test.com",
      password: "TestPassword!2",
      role_id: typia.random<string & tags.Format<"uuid">>(),
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(fakeUser);

  // 2. Attempt to delete a vote with a random, clearly non-existent UUID
  const nonExistentVoteId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete non-existent vote should fail")(() =>
    api.functional.bbs.votes.eraseById(connection, { id: nonExistentVoteId })
  );

  // 3. Attempting to delete an already deleted vote would require a creation endpoint, which is not available here. Skipped.

  // 4. (If response body includes error details, further assertions could be made.)
}

