import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IPageBbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing posts with valid search, filter, and pagination parameters.
 *
 * This test covers the following scenario: A user registers, categories are created, and the user creates multiple posts in various categories.
 * The test then requests a paginated list of posts filtered by a specific category, sorted by creation date, and using realistic page size and offset.
 * The response is validated to ensure that only posts matching the filter are returned, that pagination constraints are respected (limit/page correctness),
 * and that the pagination metadata (e.g., total record count, current page) is accurate.
 *
 * Steps:
 * 1. Register a new user (fetching a usable user_role_id and providing appropriate credentials).
 * 2. Create multiple categories.
 * 3. Create multiple posts across the created categories, assigning some to each category.
 * 4. Select one category and a subset of posts with that category.
 * 5. Request a paginated/sorted/filtered list of posts using the /bbs/posts PATCH endpoint, filtering by the chosen category,
 *    sorted by creation date descending, limited to a page size (e.g., 2), and requesting the first page.
 * 6. Validate that the returned posts belong only to the correct category, total records/pagination info is accurate, and sorting is honored.
 */
export async function test_api_bbs_test_list_posts_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Register a user (requires a valid user_role_id)
  // For test, we'll randomly generate a UUID for user_role_id. In real test, would fetch an actual role or seed data.
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const userInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    bio: RandomGenerator.paragraph()(),
    role_id: userRoleId,
  } satisfies IBbsUsers.ICreate;
  const user = await api.functional.bbs.users.post(connection, { body: userInput });
  typia.assert(user);

  // 2. Create multiple categories
  const categoriesToCreate = 3;
  const createdCategories = [];
  for (let i = 0; i < categoriesToCreate; ++i) {
    const categoryInput = {
      name: RandomGenerator.alphabets(6) + i,
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate;
    const category = await api.functional.bbs.categories.post(connection, { body: categoryInput });
    createdCategories.push(category);
    typia.assert(category);
  }
  // 3. Create multiple posts across those categories
  const postsPerCategory = 3;
  const allPosts: bbsPosts[] = [];
  for (let i = 0; i < createdCategories.length; ++i) {
    for (let j = 0; j < postsPerCategory; ++j) {
      const postInput = {
        category_id: createdCategories[i].id,
        title: `Test Post ${i}-${j}`,
        content: RandomGenerator.paragraph()(),
      } satisfies bbsPosts.ICreate;
      const post = await api.functional.bbs.posts.post(connection, { body: postInput });
      typia.assert(post);
      allPosts.push(post);
    }
  }
  // 4. Pick a filter category and determine the expected posts
  const filterCategory = createdCategories[1];
  const postsInCategory = allPosts.filter(p => p.category_id === filterCategory.id);
  // Sort postsInCategory by created_at desc
  postsInCategory.sort((a, b) => b.created_at.localeCompare(a.created_at));
  const page = 1;
  const limit = 2;
  const expectedPagePosts = postsInCategory.slice((page - 1) * limit, page * limit);
  // 5. Request list with filter, sort, and pagination
  const listResponse = await api.functional.bbs.posts.patch(connection, {
    body: {
      category_id: filterCategory.id,
      sort_by: "created_at",
      order: "desc",
      page,
      limit,
    },
  });
  typia.assert(listResponse);
  // 6. Validate response: posts are only from category, correct limit, correct metadata, correct sort
  TestValidator.equals("pagination current page")(page)(listResponse.pagination.current);
  TestValidator.equals("pagination limit")(limit)(listResponse.pagination.limit);
  TestValidator.equals("pagination records count")(postsInCategory.length)(listResponse.pagination.records);
  TestValidator.equals("pagination pages count")(Math.ceil(postsInCategory.length / limit))(listResponse.pagination.pages);
  TestValidator.equals("item count should be not exceed limit or category size")(
    Math.min(limit, postsInCategory.length),
  )(listResponse.data.length);
  for (const [idx, post] of listResponse.data.entries()) {
    TestValidator.equals("category_id for post")(filterCategory.id)(post.category_id);
    TestValidator.equals("sorted order")(expectedPagePosts[idx]?.id)(post.id);
  }
}

