import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { IPageBbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageBbsPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing posts with valid search, filter, and pagination parameters.
 *
 * This E2E test verifies that the posts listing endpoint returns posts correctly filtered by category,
 * sorted by creation date, and paginated as requested. It creates a test user, several categories,
 * and several posts, then retrieves a filtered post list with a page size, verifying all critical
 * expectations (filter, sort, pagination metadata) are met.
 *
 * Steps:
 * 1. Register a test user (require user_role_id; for this test, use a random UUID).
 * 2. Create multiple categories (ensure unique names).
 * 3. Create several posts in each category using the test user as author.
 * 4. Choose one category and determine the posts that should match the filter.
 * 5. Request a paginated, sorted, filtered list for the chosen category (page 1, limit 2, sorted desc).
 * 6. Validate:
 *    - All returned posts belong to the filter category.
 *    - The number of returned posts is limited by pagination.
 *    - Sorting by created_at desc is respected.
 *    - Pagination metadata (current, limit, records, pages) are correct.
 */
export async function test_api_bbs_test_list_posts_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a test user (requires a valid user_role_id)
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create multiple categories
  const NUM_CATEGORIES = 3;
  const categories: bbsCategories[] = [];
  for (let i = 0; i < NUM_CATEGORIES; ++i) {
    const category = await api.functional.bbs.categories.post(connection, {
      body: {
        name: `${RandomGenerator.alphabets(6)}${i}`,
        description: RandomGenerator.paragraph()(),
      } satisfies bbsCategories.ICreate,
    });
    typia.assert(category);
    categories.push(category);
  }

  // 3. Create several posts per category
  const POSTS_PER_CATEGORY = 3;
  const posts: bbsPosts[] = [];
  for (const category of categories) {
    for (let j = 0; j < POSTS_PER_CATEGORY; ++j) {
      const post = await api.functional.bbs.posts.post(connection, {
        body: {
          category_id: category.id,
          title: `Test Post ${category.name}-${j}`,
          content: RandomGenerator.paragraph()(),
        } satisfies bbsPosts.ICreate,
      });
      typia.assert(post);
      posts.push(post);
    }
  }

  // 4. Choose a filter category and determine filtered posts
  const targetCategory = categories[1];
  const postsInCategory = posts.filter(post => post.category_id === targetCategory.id);

  // Sort by created_at descending to match API sort order
  postsInCategory.sort((a, b) => b.created_at.localeCompare(a.created_at));

  const page = 1;
  const limit = 2;
  const expectedPagePosts = postsInCategory.slice((page - 1) * limit, page * limit);

  // 5. Query the listing endpoint with category filter, sort, and pagination
  const result = await api.functional.bbs.posts.patch(connection, {
    body: {
      category_id: targetCategory.id,
      sort_by: "created_at",
      order: "desc",
      page,
      limit,
    },
  });
  typia.assert(result);

  // 6. Validate the response contents and pagination metadata
  TestValidator.equals("current page")(page)(result.pagination.current);
  TestValidator.equals("limit")(limit)(result.pagination.limit);
  TestValidator.equals("total records")(postsInCategory.length)(result.pagination.records);
  TestValidator.equals("total pages")(Math.ceil(postsInCategory.length / limit))(result.pagination.pages);
  TestValidator.equals("response count should match expected or leftover")(
    Math.min(limit, postsInCategory.length),
  )(result.data.length);

  // All returned posts must match the category and be in the right order
  for (const [idx, post] of result.data.entries()) {
    TestValidator.equals("category_id matches filter")(targetCategory.id)(post.category_id);
    TestValidator.equals("sorted order matches expected")(expectedPagePosts[idx]?.id)(post.id);
  }
}

