 *
 * This scenario covers attempts to search or paginate the posts list using invalid inputs or unsupported filter keys. The API should properly return validation errors and must not leak any posts from the database.
 *
 * Step-by-step process:
 * 1. Create a valid user (via /bbs/users POST) for API authentication/context, even if not strictly necessary for endpoint access.
 * 2. Attempt to list posts with invalid parameters:
 *    - Negative 'limit' value (e.g., limit: -10)
 *    - Negative 'page' value (e.g., page: -1)
 *    - Non-existent 'category_id' (random UUID)
 *    - Unsupported value for 'sort_by' or 'order' (e.g., 'sort_by': 'invalid-field', 'order': 'sideways')
 *    - Completely extra/unknown fields (should be ignored or rejected)
 * 3. For each invalid request, confirm:
 *    - The response contains a clear validation error (using TestValidator.error)
 *    - No database records (posts) are returned on error
 *    - Error message is descriptive and non-leaking of DB internals
 * 4. (Edge) Confirm that a valid request (with all valid params) still returns a response as expected (IPageBbsPosts).
 */
export async function test_api_bbs_test_list_posts_invalid_parameters(
  connection: api.IConnection,
) {
