  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password1!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Define invalid parameter test cases
  const invalidRequests = [
    { body: { limit: -10 } }, // Negative limit
    { body: { page: -1 } }, // Negative page
    { body: { category_id: typia.random<string & tags.Format<"uuid">>() } }, // Non-existent UUID (invalid category)
    { body: { sort_by: "invalid-field" as any } }, // Invalid sort_by
    { body: { order: "sideways" as any } }, // Invalid order
    { body: { non_existing_key: "should-fail" } as any }, // Extra field
  ];

  // 3. Each should cause validation error, never success
  for (const req of invalidRequests) {
    await TestValidator.error("invalid posts listing params fail")(async () => {
      await api.functional.bbs.posts.patch(connection, req as { body: bbsPosts.IRequest });
    });
  }

  // 4. Control: Do a valid request for sanity
  const validOutput = await api.functional.bbs.posts.patch(connection, {
    body: {},
  });
  typia.assert(validOutput);
