  TestValidator.equals("내용")(postContent)(post.content);
  TestValidator.equals("category_id")(category.id)(post.category_id);
  TestValidator.equals("user_id")(user.id)(post.user_id);
  TestValidator.predicate("created_at 타입 확인")(
