import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate API rejection when attempting to create a post with missing or invalid data.
 *
 * Business context: The BBS platform enforces strict requirements for post creation (non-empty title/content, valid category ID). Attempts to bypass these constraints must result in validation errors and no post creation. This is critical for both data quality and user experience.
 *
 * Test Flow:
 * 1. Prepare authentication context by creating a user (using dependency).
 * 2. Attempt to create a post with each of the following invalid scenarios, and ensure the API rejects them with appropriate validation errors:
 *    a. Missing title (empty string)
 *    b. Missing content (empty string)
 *    c. Missing category_id (invalid or empty UUID)
 *    d. Non-existent/random category_id (well-formed but not present in DB)
 *    e. Title or content containing invalid characters or excessive length (if applicable to the platform)
 *    f. All fields empty
 * 3. Verify that for each rejected attempt, the API responds with a clear validation error.
 * 4. Confirm that no new post is created as a result of failed attempts.
 *
 * Steps:
 * - Create/register a user to act as the author/auth context
 * - For each test case:
 *   - Submit a post creation request with the specific type of invalid data
 *   - Catch the error and assert it is a validation error (not a success)
 *   - Optionally, query for posts for the user and ensure no invalid post was created
 */
export async function test_api_bbs_test_create_post_with_missing_or_invalid_data(connection: api.IConnection) {
  // 1. User registration (dependency from scenario)
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: `${RandomGenerator.alphaNumeric(8)}@test.com`,
      password: RandomGenerator.alphaNumeric(10),
      role_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // Helper: valid fake category UUID, but not in DB
  const fakeCategoryId = typia.random<string & tags.Format<"uuid">>();

  // Define invalid input scenarios
  const invalidCases = [
    { desc: "empty title", body: { category_id: fakeCategoryId, title: "", content: "Valid content" } },
    { desc: "empty content", body: { category_id: fakeCategoryId, title: "Valid Title", content: "" } },
    { desc: "empty category_id", body: { category_id: "", title: "Some Title", content: "Some Content" } },
    { desc: "invalid format category_id", body: { category_id: "not-a-uuid", title: "Some Title", content: "Some Content" } },
    { desc: "non-existent category_id", body: { category_id: fakeCategoryId, title: "Some Title", content: "Some Content" } },
    { desc: "excessive long title", body: { category_id: fakeCategoryId, title: RandomGenerator.alphaNumeric(1025), content: "Some Content" } },
    { desc: "all fields empty", body: { category_id: "", title: "", content: "" } }
  ];

  for (const testCase of invalidCases) {
    await TestValidator.error(`should reject post: ${testCase.desc}`)(async () => {
      await api.functional.bbs.posts.post(connection, { body: testCase.body });
    });
  }
  // Optionally, attempt to fetch user's posts and expect empty result (if platform allows)
}

