export async function test_api_bbs_test_update_post_with_valid_data_by_author(
  connection: api.IConnection,
) {
  // 1. Register a new user (author)
  const role_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphabets(8);
  const email = `${username.toLowerCase()}@test.com`;
  const password = "Test!234";
  const author = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      role_id,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(author);

  // 2. Create two categories (initial and target)
  const initialCategory = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(initialCategory);
  const targetCategory = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(targetCategory);

  // 3. Have the user create a post in the initial category
  const originalTitle = RandomGenerator.paragraph()(1);
  const originalContent = RandomGenerator.content()()();
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: initialCategory.id,
      title: originalTitle,
      content: originalContent,
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Prepare new valid data and perform update
  const updatedTitle = RandomGenerator.paragraph()(1) + " Updated";
  const updatedContent = RandomGenerator.content()()() + " + more";
  const updatePayload = {
    category_id: targetCategory.id,
    title: updatedTitle,
    content: updatedContent,
  } satisfies bbsPosts.IUpdate;

  const updated = await api.functional.bbs.posts.putById(connection, {
    id: post.id,
    body: updatePayload,
  });
  typia.assert(updated);

  // 5. Assert values are updated
  TestValidator.equals("post.id")(post.id)(updated.id);
  TestValidator.equals("updated category")(targetCategory.id)(updated.category_id);
  TestValidator.equals("updated title")(updatedTitle)(updated.title);
  TestValidator.equals("updated content")(updatedContent)(updated.content);

  // 6. Confirm timestamps reflect update
  TestValidator.notEquals("created_at should not change")(null)(updated.created_at);
  TestValidator.notEquals("updated_at should advance for update")(post.updated_at)(updated.updated_at);

  // 7. Constraints: updated fields cannot be empty (should fail if attempted, but this case handled in negative tests)
}

