import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that the post update API properly rejects invalid updates and does not alter the existing post when errors occur.
 *
 * Business context:
 * Post updates must not allow use of invalid category references, duplicate or empty titles, or the inclusion of forbidden words/content. The server must return detailed validation errors and leave post data untouched on failure.
 *
 * Steps:
 * 1. Create a test user (author).
 * 2. Create two categories (cat1, cat2) to support valid and duplicate category/title tests.
 * 3. Create an initial post (with cat1/category and valid title/content).
 * 4. Test update attempts with these invalid input cases:
 *    a. Non-existent category_id (random UUID not present in categories DB)
 *    b. Duplicate title (create post2 with cat2 and post2-title, then assign that same title in update)
 *    c. Empty title
 *    d. Title/content with forbidden phrase (e.g., 'spamword')
 * 5. For each attempt: Call PUT /bbs/posts/{id} with invalid input, confirm error is returned, and post remains unchanged by retrieving it after the failed update.
 */
export async function test_api_bbs_test_update_post_with_invalid_data(connection: api.IConnection) {
  // 1. Create a user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: `${RandomGenerator.alphabets(6)}@mail.com`,
      password: 'TestPassword123!',
      bio: 'E2E test user',
      role_id: typia.random<string & tags.Format<'uuid'>>()
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create two categories
  const cat1 = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: 'Test category one'
    } satisfies bbsCategories.ICreate
  });
  typia.assert(cat1);

  const cat2 = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(12),
      description: 'Test category two'
    } satisfies bbsCategories.ICreate
  });
  typia.assert(cat2);

  // 3. Create an initial post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: cat1.id,
      title: 'Initial Test Post',
      content: 'Valid post for invalid update test.'
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 4a. Attempt to update post with non-existent category_id
  const badCategoryId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error('should fail on non-existent category')(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: badCategoryId,
        title: post.title,
        content: post.content
      } satisfies bbsPosts.IUpdate
    })
  );

  // Ensure post is unchanged
  const read1 = await api.functional.bbs.posts.post(connection, { body: { category_id: cat1.id, title: post.title, content: post.content } });
  TestValidator.equals('post unchanged')(post)(read1);

  // 4b. Attempt to update post with duplicate title
  const post2 = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: cat2.id,
      title: 'Duplicate Title',
      content: 'Another post for duplicate title test.'
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post2);
  await TestValidator.error('should fail on duplicate title')(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: cat1.id,
        title: post2.title,
        content: 'Trying duplicate title.'
      } satisfies bbsPosts.IUpdate
    })
  );
  // Ensure post is unchanged
  const read2 = await api.functional.bbs.posts.post(connection, { body: { category_id: cat1.id, title: post.title, content: post.content } });
  TestValidator.equals('post unchanged')(post)(read2);

  // 4c. Attempt to update post with empty title
  await TestValidator.error('should fail on empty title')(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: cat1.id,
        title: '',
        content: 'Content for empty title.'
      } satisfies bbsPosts.IUpdate
    })
  );
  const read3 = await api.functional.bbs.posts.post(connection, { body: { category_id: cat1.id, title: post.title, content: post.content } });
  TestValidator.equals('post unchanged')(post)(read3);

  // 4d. Attempt to update post with forbidden content
  await TestValidator.error('should fail on forbidden content')(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: {
        category_id: cat1.id,
        title: 'Clean Title',
        content: 'This content contains spamword which is forbidden.'
      } satisfies bbsPosts.IUpdate
    })
  );
  const read4 = await api.functional.bbs.posts.post(connection, { body: { category_id: cat1.id, title: post.title, content: post.content } });
  TestValidator.equals('post unchanged')(post)(read4);
}

