import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Validate that unauthorized users (neither the post's original author nor privileged, e.g. admin/mod) are denied when attempting to update a post.
 *
 * This test ensures correct enforcement of update permissions on posts in the BBS platform: only the original author or authorized privileged roles may update a post's content or metadata. All other users must be denied.
 *
 * Workflow:
 * 1. Register a basic non-privileged user who will be the post's author.
 * 2. Register a second distinct regular user lacking privileges.
 * 3. Admin creates a category (required for post creation).
 * 4. First user creates a post in the given category.
 * 5. Switch to second (non-author) user.
 * 6. Attempt to update the post's content via the API. Expect an authorization (permission) failure, not a validation error. The API should reject the request with an error status (typically 403 Forbidden or similar), and must not modify the original post.
 * 7. (Optional) Re-fetch the post as the original author or via a privileged user and verify that the post's content is unchanged.
 */
export async function test_api_bbs_test_update_post_by_non_author_or_non_privileged_user(connection: api.IConnection) {
  // 1. Register two regular "member" users (author and non-author)
  const memberRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  // UserA - the original author
  const authorEmail: string = typia.random<string & tags.Format<"email">>();
  const authorPassword = "authorPW!123";
  const author = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: authorEmail,
      password: authorPassword,
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(author);

  // UserB - non-privileged, non-author user
  const attackerEmail: string = typia.random<string & tags.Format<"email">>();
  const attackerPassword = "attackerPW!456";
  const attacker = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: attackerEmail,
      password: attackerPassword,
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(attacker);

  // 2. Create a category (using assumed admin privilege in test context)
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Author creates a post in the new category
  // Assume test infra allows login as different users by updating connection headers
  await api.functional.bbs.users.post(connection, {
    body: {
      username: author.username,
      email: author.email,
      password: authorPassword,
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  }); // re-login as author if necessary (idempotent call)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Switch to non-author user (attacker) for update attempt
  // (Assuming session switch by logging in or setting token)
  await api.functional.bbs.users.post(connection, {
    body: {
      username: attacker.username,
      email: attacker.email,
      password: attackerPassword,
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  }); // re-login as attacker (idempotent call)

  // 5. Attempt to update the post as the non-author, expect authorization error
  const updatedData: bbsPosts.IUpdate = {
    category_id: category.id,
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.content()()(),
  };
  await TestValidator.error("update by non-author should fail")(() =>
    api.functional.bbs.posts.putById(connection, {
      id: post.id,
      body: updatedData,
    })
  );

  // 6. Optional: Switch back to author and verify content unchanged
  await api.functional.bbs.users.post(connection, {
    body: {
      username: author.username,
      email: author.email,
      password: authorPassword,
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });

  // (Assume GET endpoint for post exists; if not, skip below)
