import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Test deletion of a board post by its author, verifying correct behavior (soft delete or hard delete).
 *
 * This test validates that an authenticated user (the post author) is able to delete their own post.
 * It covers business rules requiring registration, category association and user authentication.
 *
 * Steps:
 * 1. Register a user (author)
 * 2. Create a category
 * 3. Create a post under this category as the user
 * 4. Delete the post as the same user
 * 5. Assert that the response indicates success (returned post marked as deleted or record removed)
 * 6. (Optional) Verify that the post no longer appears in detail lookup or list queries if API exposes such
 */
export async function test_api_bbs_test_delete_post_by_author(connection: api.IConnection) {
  // 1. Register user
  const userRoleId = typia.random<string & tags.Format<"uuid">>(); // Normally would use known role, here: random
  const username = RandomGenerator.alphaNumeric(10);
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);

  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio: RandomGenerator.paragraph()(),
      role_id: userRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);
  // (If auth is required for post creation, connection must inherit this user's token)

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. Create post as user
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Delete the post as user (by ID)
  const deleted = await api.functional.bbs.posts.eraseById(connection, {
    id: post.id,
  });
  typia.assert(deleted);
  // 5. Assert that post is marked as deleted (soft delete - deleted_at set)
  TestValidator.predicate("post soft deleted")(!!deleted.deleted_at);

  // 6. (If lookup API is available) Try to fetch post, expect not found or marked as deleted
}

