import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";

/**
 * Verify that deleting a post by a non-author user without necessary privileges is not permitted and does not leak sensitive information.
 *
 * This test ensures robust authorization logic by simulating a scenario where two users exist:
 * - User A is the author of a post
 * - User B is a general member with no moderation powers
 *
 * Steps:
 * 1. Register two users (User A = author, User B = attacker) each with ordinary member role
 * 2. Create a category to post in
 * 3. User A creates a post in the category
 * 4. User B attempts to delete User A's post (should be rejected)
 * 5. Validate that deletion fails, no sensitive info is leaked, and the post remains present (not deleted)
 */
export async function test_api_bbs_test_delete_post_by_non_author(
  connection: api.IConnection,
) {
  // 1. Register two users (A = author, B = attacker)
  const memberRoleId: string = typia.random<string & tags.Format<"uuid">>();
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: `${RandomGenerator.alphabets(8)}@test.com`,
      password: "password123!",
      bio: "Author user for test.",
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: `${RandomGenerator.alphabets(8)}@test.com`,
      password: "password123!",
      bio: "Non-author user for test.",
      role_id: memberRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // 2. Create a test category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1, 3),
      description: RandomGenerator.paragraph()(3, 6),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. User A creates a post in the category
  // (Emulate authenticated User A context if necessary)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1, 3),
      content: RandomGenerator.paragraph()(3, 6),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. User B attempts to delete User A's post
  let deletionFailed = false;
  try {
    await api.functional.bbs.posts.eraseById(connection, { id: post.id });
  } catch (err) {
    deletionFailed = true;
    // Optionally: inspect err to confirm error has no leaked info
    // e.g., TestValidator.predicate('Error message sanitized')(...)
  }
  TestValidator.predicate("Non-author user's deletion is rejected")(deletionFailed);

  // 5. Confirm that the post remains present and not deleted (best effort)
  // No GET endpoint for post in available SDK list; if provided, validate post not deleted.
}

