import { tags } from "typia";

export namespace IPage {
  /**
   * Pagination information for paginated results. Used in all IPage<T>
   * structures; see standard type definition.
   */
  export type IPagination = {
    /** Current page number. */
    current: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Number of records per page. Default is 100. */
    limit: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Total number of records in the result set. */
    records: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;

    /** Total pages. Equal to records/limit with ceiling. */
    pages: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "uint32";
      }>;
  };
}

