import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IPageIBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUsers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test paginated and filtered user listing for moderators/administrators.
 *
 * This test ensures that a privileged user (administrator/moderator) can retrieve '
 * a paginated, filtered user list:
 *
 * 1. Set up several users (diverse usernames, emails, roles, statuses) to support meaningful filtering/pagination (via dependency).
 * 2. Authenticate as an admin (token-based auth assumed for API connection).
 * 3. Use PATCH /bbs/users to search for users:
 *    - Use a username substring filter (partial match for one/all seeded users)
 *    - Use an email domain filter (partial match for one/all seeded users)
 *    - Use a status filter (e.g., active)
 *    - Use low limit for pagination (e.g., limit=2), request page 1
 * 4. Confirm:
 *    - Response includes only users matching filters
 *    - Each user record contains non-sensitive, expected fields (never password)
 *    - Pagination metadata reflects collection size
 *    - All returned data conforms to IBbsUsers and IPageIBbsUsers
 */
export async function test_api_bbs_test_list_users_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several users with diverse attributes
  const adminUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: "modadmin_" + RandomGenerator.alphaNumeric(5),
      email: "modadmin+" + RandomGenerator.alphaNumeric(4) + "@corp.test",
      password: "StrongPass!234",
      bio: "I am the admin account.",
      role_id: typia.random<string & tags.Format<"uuid">>()
    }
  });
  typia.assert(adminUser);

  const matchingUsername = "alice" + RandomGenerator.alphaNumeric(3);
  const matchingEmail = "alice@company.org";
  const users = [
    await api.functional.bbs.users.post(connection, {
      body: {
        username: matchingUsername,
        email: matchingEmail,
        password: "Pw!23456",
        bio: "First test user.",
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    }),
    await api.functional.bbs.users.post(connection, {
      body: {
        username: "bob" + RandomGenerator.alphaNumeric(2),
        email: "bob@provider.net",
        password: "Pw!ABC345",
        bio: null,
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    }),
    await api.functional.bbs.users.post(connection, {
      body: {
        username: "carol" + RandomGenerator.alphaNumeric(2),
        email: "carol@example.com",
        password: "AnotherPW!12",
        bio: "Yet another test user.",
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    }),
    await api.functional.bbs.users.post(connection, {
      body: {
        username: "active_user" + RandomGenerator.alphaNumeric(1),
        email: "active@corp.test",
        password: "Active!4321",
        bio: null,
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    })
  ];
  users.forEach(u => typia.assert(u));

  // 2. Assume admin is authenticated (token installed on connection)

  // 3. Request: filter by username (partial), email (domain), status, pagination
  const filterParams = {
    page: 1,
    limit: 2,
    username: "alice", // substring
    email: "@company.org", // domain filter
    status: users[0].status // status from the matching user
  } satisfies IBbsUsers.IRequest;
  const pageResult = await api.functional.bbs.users.patch(connection, {
    body: filterParams
  });
  typia.assert(pageResult);

  // 4. Verify response: all users should match filters
  for (const user of pageResult.data) {
    TestValidator.predicate("username contains filter")(
      user.username.includes(filterParams.username ?? "")
    );
    TestValidator.predicate("email contains filter")(
      user.email.includes(filterParams.email ?? "")
    );
    TestValidator.equals("status matches filter")(filterParams.status)(user.status);
    TestValidator.predicate("No sensitive fields returned")(
      !("password" in user)
    );
    // Optionally assert more required fields exist
    typia.assert(user);
  }
  // 5. Verify pagination metadata
  const { pagination } = pageResult;
  TestValidator.equals("page matches")(pagination.current)(filterParams.page);
  TestValidator.equals("limit matches")(pagination.limit)(filterParams.limit);
  TestValidator.predicate("records >= data.length")(pagination.records >= pageResult.data.length);
}

