      body: {
        username: matchingUsername,
        email: matchingEmail,
        password: "Pw!23456",
        bio: "First test user.",
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    }),
    await api.functional.bbs.users.post(connection, {
