        email: "active@corp.test",
        password: "Active!4321",
        bio: null,
        role_id: typia.random<string & tags.Format<"uuid">>()
      }
    })
  ];
  users.forEach(u => typia.assert(u));

  // 2. Assume admin is authenticated (token installed on connection)

  // 3. Request: filter by username (partial), email (domain), status, pagination
  const filterParams = {
    page: 1,
    limit: 2,
    username: "alice", // substring
    email: "@company.org", // domain filter
    status: users[0].status // status from the matching user
  } satisfies IBbsUsers.IRequest;
  const pageResult = await api.functional.bbs.users.patch(connection, {
    body: filterParams
