  for (const user of pageResult.data) {
    TestValidator.predicate("username contains filter")(
      user.username.includes(filterParams.username ?? "")
    );
    TestValidator.predicate("email contains filter")(
      user.email.includes(filterParams.email ?? "")
    );
    TestValidator.equals("status matches filter")(filterParams.status)(user.status);
    TestValidator.predicate("No sensitive fields returned")(
      !("password" in user)
    );
