import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate that a standard/non-privileged user cannot access another user's profile.
 *
 * Business context:
 * Platforms restrict account/profile visibility so only privileged roles (e.g., moderators or admins), or the user themselves, can access detailed profile/account records of other users. This security policy protects user privacy and enforces separation of permissions.
 *
 * This test ensures that a standard user (not admin/moderator nor the owner of the target profile) cannot access another user's detailed profile using GET /bbs/users/{id}. The attempt must result in an access denied/forbidden error.
 *
 * Step-by-step process:
 * 1. Register/create two standard (non-privileged) users
 * 2. Attempt to access second user's profile as the first user
 * 3. Assert access is denied with a permission error (not authorized)
 */
export async function test_api_bbs_test_get_user_profile_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Register two standard users
  // For realistic testing, their role_id must NOT be for admin/moderator roles
  // -- since only standard user roles are provided in DTO, we use random UUID for role_id
  const standardRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // Register USER A (requestor)
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: userAEmail,
      password: "TestPassword1!",
      role_id: standardRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  // Register USER B (target profile)
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: userBEmail,
      password: "TestPassword1!",
      role_id: standardRoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // 2. Attempt to access User B's profile as User A
  //    (non-admin user, not their own profile)
  await TestValidator.error("should deny access to another user's profile")(() =>
    api.functional.bbs.users.getById(connection, {
      id: userB.id,
    })
  );
}

