import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test duplicate user registration handling.
 *
 * Validates that the user registration API rejects attempts to register a new user with an email or username that already exists in the system.
 *
 * 1. Fetch the list of available user roles to ensure a valid role_id can be assigned.
 * 2. Register the initial user with a randomly generated unique username and email.
 * 3. Attempt to register a new user with the same email but a different username, expecting an error response (uniqueness violation for email).
 * 4. Attempt to register a different user with the same username but a different email, expecting an error (uniqueness violation for username).
 * 5. If either duplicate attempt succeeds, the test must fail.
 */
export async function test_api_bbs_test_create_user_with_duplicate_email_or_username(connection: api.IConnection) {
  // 1. Fetch user roles
  const rolesPage = await api.functional.bbs.userRoles.patch(connection, {
    body: { page: 1, limit: 10 }
  });
  typia.assert(rolesPage);
  const firstRole = rolesPage.data[0];
  if (!firstRole)
    throw new Error("No user roles available for assignment");

  // 2. Register initial user
  const baseUser = {
    username: RandomGenerator.alphaNumeric(8),
    email: RandomGenerator.alphaNumeric(8) + "@example.com",
    password: "Password123!",
    bio: RandomGenerator.paragraph()(1),
    role_id: firstRole.id
  } satisfies IBbsUsers.ICreate;
  const createdUser = await api.functional.bbs.users.post(connection, { body: baseUser });
  typia.assert(createdUser);

  // 3. Attempt duplicate email
  await TestValidator.error("Duplicate email should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: baseUser.email,
        password: "Password321!",
        bio: RandomGenerator.paragraph()(1),
        role_id: firstRole.id
      } satisfies IBbsUsers.ICreate
    })
  );

  // 4. Attempt duplicate username
  await TestValidator.error("Duplicate username should fail")(() =>
    api.functional.bbs.users.post(connection, {
      body: {
        username: baseUser.username,
        email: RandomGenerator.alphaNumeric(8) + "@other.com",
        password: "Password231!",
        bio: RandomGenerator.paragraph()(1),
        role_id: firstRole.id
      } satisfies IBbsUsers.ICreate
    })
  );
}

