import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { IPageIBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsUserRoles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate registration failures on user creation due to invalid role references and input format errors (email, username, password).
 *
 * This test ensures that the registration endpoint enforces validation rules for both references (invalid role id) and required fields (email format, password strength, username format).
 * The test first fetches existing valid roles, then proceeds to test multiple negative scenarios:
 *   1. Attempts to register with a non-existent or malformed role_id
 *   2. Attempts to register with improperly formatted email addresses
 *   3. Attempts to register with weak/invalid passwords
 *   4. Attempts to register with invalid usernames (if there are specific constraints)
 * For each attempt, the test expects the API to return a validation error identifying the failure.
 *
 * Steps:
 * 1. Fetch the valid user roles from the API to know what constitutes a valid reference
 * 2. Attempt user registration with a random UUID (not present in valid roles) as role_id
 * 3. Attempt user registration with a valid role_id but an invalid email format
 * 4. Attempt user registration with a valid role_id but a weak/invalid password
 * 5. (Optional) Attempt user registration with invalid username if business rules exist
 * 6. For all expected failures, assert that the API responds with a validation error and identifies which field failed
 */
export async function test_api_bbs_test_create_user_with_invalid_role_or_format(connection: api.IConnection) {
  // 1. Fetch valid user roles to obtain correct role_id
  const userRolesPage = await api.functional.bbs.userRoles.patch(connection, {
    body: {},
  });
  typia.assert(userRolesPage);
  const validRoleIds = userRolesPage.data.map(role => role.id);
  // Create an invalid role_id (guaranteed not to be in valid roles)
  let invalidRoleId;
  do {
    invalidRoleId = typia.random<string & tags.Format<"uuid">>();
  } while (validRoleIds.includes(invalidRoleId));

  // 2. Attempt registration with invalid role_id
  await TestValidator.error("register with invalid role_id fails")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: `${RandomGenerator.alphabets(5)}@example.com`,
        password: "StrongPassword123!",
        role_id: invalidRoleId,
      } satisfies IBbsUsers.ICreate,
    });
  });

  // 3. Attempt registration with invalid email
  const validRoleId = validRoleIds[0];
  await TestValidator.error("register with invalid email fails")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: "not-an-email",
        password: "StrongPassword123!",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    });
  });

  // 4. Attempt registration with invalid password (too short)
  await TestValidator.error("register with weak password fails")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: `${RandomGenerator.alphabets(5)}@example.com`,
        password: "123",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    });
  });

  // 5. Optionally, test other field validations (username constraints)
  await TestValidator.error("register with invalid username fails")(async () => {
    await api.functional.bbs.users.post(connection, {
      body: {
        username: "", // empty username (invalid)
        email: `${RandomGenerator.alphabets(5)}@example.com`,
        password: "StrongPassword123!",
        role_id: validRoleId,
      } satisfies IBbsUsers.ICreate,
    });
  });
}

