import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Test that a user can update their own profile with valid data.
 *
 * Business context:
 * - A registered user should be able to update their profile (username, email, bio, and role if permitted) with valid and unique data.
 * - The test must ensure that after profile update, all changes are reflected in the response and no uniqueness/integrity constraints are violated (e.g., username/email uniqueness, role remains assigned correctly).
 *
 * Steps:
 * 1. Register a new user via api.functional.bbs.users.post.
 * 2. Update the user's profile using api.functional.bbs.users.putById, changing username, email, bio, and providing a new valid role_id (for the sake of test, random uuid for role_id).
 * 3. Assert the response: all updated fields match requested data, id remains unchanged, and role property in response reflects the new role assignment.
 * 4. (Optional) Try updating with the same email as before to prove uniqueness is maintained (integrity test).
 */
export async function test_api_bbs_test_update_user_profile_as_self_with_valid_data(connection: api.IConnection) {
  // 1. Register a new user
  const registered = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      bio: RandomGenerator.paragraph()(1),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(registered);

  // 2. Prepare update payload (change username, email, bio, and role_id)
  const newProfile = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    bio: RandomGenerator.paragraph()(2),
    role_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IBbsUsers.IUpdate;

  // 3. Update user's profile
  const updated = await api.functional.bbs.users.putById(connection, {
    id: registered.id,
    body: newProfile,
  });
  typia.assert(updated);

  // 4. Assert updates are applied and id did not change
  TestValidator.equals("id unchanged")(registered.id)(updated.id);
  TestValidator.equals("username updated")(newProfile.username)(updated.username);
  TestValidator.equals("email updated")(newProfile.email)(updated.email);
  TestValidator.equals("bio updated")(newProfile.bio)(updated.bio);
  TestValidator.equals("role_id updated")(newProfile.role_id)(updated.user_role_id);

  // 5. (Integrity) Try to update to the same email again (should succeed)
  const again = await api.functional.bbs.users.putById(connection, {
    id: registered.id,
    body: { email: newProfile.email } satisfies IBbsUsers.IUpdate,
  });
  typia.assert(again);
  TestValidator.equals("email remains same")(newProfile.email)(again.email);
}

