import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";

/**
 * Validate protection of user profile update endpoint.
 *
 * This test ensures that a non-privileged user (neither admin nor the target user) cannot update another user's profile.
 * It first registers two standard user accounts (userA and userB). Then userA, using a valid session, attempts to update userB's profile with a well-formed payload. The test must verify that the API responds with a permission denied or forbidden error; no changes should be applied to userB's account.
 *
 * Steps:
 * 1. Register userA (standard user)
 * 2. Register userB (another standard user)
 * 3. Log in as userA
 * 4. Attempt to PUT update userB's profile data as userA, using a valid update payload
 * 5. Confirm API returns a 403 Forbidden (or appropriate error) and userB's profile is unmodified.
 */
export async function test_api_bbs_test_update_other_user_profile_without_admin_permission(
  connection: api.IConnection,
) {
  // 1. Register userA (standard user, with unique role_id)
  const userARoleId = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userA: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: userAEmail,
      password: "TestPasswordA!2024",
      bio: "userA bio",
      role_id: userARoleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  // 2. Register userB (another standard user, same or similar role_id)
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userB: IBbsUsers = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: userBEmail,
      password: "TestPasswordB!2024",
      bio: "userB bio",
      role_id: userARoleId, // Both standard
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // 3. Log in as userA
  if (api.functional.bbs.users.authenticate && api.functional.bbs.users.authenticate.login) {
    await api.functional.bbs.users.authenticate.login(connection, {
      body: {
        email: userAEmail,
        password: "TestPasswordA!2024",
      },
    });
  } else {
    // If no login, assume connection is userA
  }

  // 4. Attempt to update userB's profile as userA
  const updatePayload: IBbsUsers.IUpdate = {
    bio: "malicious update attempt by userA",
  };

  await TestValidator.error("Permission denied: userA cannot update userB")(
    async () => {
      await api.functional.bbs.users.putById(connection, {
        id: userB.id,
        body: updatePayload,
      });
    },
  );
}

