 * Validate that non-privileged users cannot deactivate (soft-delete) another user's account.
 *
 * This test confirms business logic enforcing account removal restrictions: only privileged users (admins, moderators)
 * or the self-owner may deactivate or remove an account. A random non-admin user should be denied access when attempting
 * to deactivate another (target) user's account.
 *
 * Steps:
 * 1. Register two test users—one to act as the "aggressor" (non-admin) and one as the "target" for deletion.
 * 2. Authenticate as the aggressor (non-admin user).
 * 3. Attempt to call the soft-delete (deactivate) API for the target user's account using the DELETE endpoint.
 * 4. Verify that the API call fails with an error, validating insufficient privileges (forbidden/not allowed).
 * 5. Optionally, confirm the target user still exists and is active (status unchanged).
 */
export async function test_api_bbs_test_attempt_soft_delete_by_non_admin_permission_denied(connection: api.IConnection) {
  // 1. Register two users: aggressor (non-admin) and target
  const nonAdminRoleId: string = typia.random<string & tags.Format<"uuid">>(); // should correspond to a 'member' role, not an admin
  const targetRoleId: string = typia.random<string & tags.Format<"uuid">>();   // could be same or any valid role

