    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    bio: RandomGenerator.paragraph()(1),
    role_id: nonAdminRoleId,
  };
  const aggressor = await api.functional.bbs.users.post(connection, { body: aggressorInput });
  typia.assert(aggressor);

  const targetInput: IBbsUsers.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    bio: RandomGenerator.paragraph()(1),
    role_id: targetRoleId,
  };
  const target = await api.functional.bbs.users.post(connection, { body: targetInput });
  typia.assert(target);

