import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia, { tags } from "typia";
import { NestiaSimulator } from "@nestia/fetcher/lib/NestiaSimulator";

import { IBbsUsers } from "../../../structures/IBbsUsers";

/**
 * Soft-delete (deactivate) a user by status update (users table).
 *
 * This operation allows administrators or moderators to deactivate or remove a
 * user account without physically deleting the record from the database,
 * preserving audit trails and possible restoration. Actual implementation sets
 * the status field of the user record (users table) to a value like 'deleted',
 * 'banned', or 'suspended'. Only privileged users (administrators, moderators)
 * may execute this unless it's for self-removal. Associated content
 * (posts/comments) are retained. This operation references account removal
 * business logic from requirements and Prisma schema business rules. All
 * necessary validation, audit, and error handling logic are included.
 * Deactivation is irreversible except by subsequent restoration workflow.
 *
 * @param props.connection
 * @param props.id Target user's UUID
 * @path /bbs/users/:id
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function eraseById(
  connection: IConnection,
  props: eraseById.Props,
): Promise<eraseById.Response> {
  return !!connection.simulate
    ? eraseById.simulate(connection, props)
    : PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...eraseById.METADATA,
          path: eraseById.path(props),
          status: null,
        },
      );
}
export namespace eraseById {
  export type Props = {
    /** Target user's UUID */
    id: string & tags.Format<"uuid">;
  };
  export type Response = IBbsUsers;

  export const METADATA = {
    method: "DELETE",
    path: "/bbs/users/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = (props: Props) =>
    `/bbs/users/${encodeURIComponent(props.id ?? "null")}`;
  export const random = (g?: Partial<typia.IRandomGenerator>): IBbsUsers =>
    typia.random<IBbsUsers>(g);
  export const simulate = (
    connection: IConnection,
    props: eraseById.Props,
  ): Response => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: eraseById.path(props),
      contentType: "application/json",
    });
    try {
      assert.param("id")(() => typia.assert(props.id));
    } catch (exp) {
      if (!typia.is<HttpError>(exp)) throw exp;
      return {
        success: false,
        status: exp.status,
        headers: exp.headers,
        data: exp.toJSON().message,
      } as any;
    }
    return random(
      "object" === typeof connection.simulate && null !== connection.simulate
        ? connection.simulate
        : undefined,
    );
  };
}

