import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of direct replies to a parent comment with pagination.
 *
 * This function tests the workflow for listing all direct (non-nested) replies to a parent comment in a threaded discussion setting. It verifies correct structure, filtering, and content integrity for paginated replies, as well as edge case of no replies.
 *
 * Steps:
 * 1. Register a new user with a unique username and email and log in.
 * 2. Create a category to allow a post to be made.
 * 3. Have the user create a new post in the specified category.
 * 4. Add a top-level comment to the post. This will serve as the parent comment.
 * 5. Create several direct replies (children) to the parent comment.
 * 6. Optionally, add a nested reply (grandchild) to one of the direct replies to ensure only the correct level is returned.
 * 7. List replies to the parent comment using different pagination and filter configurations:
 *    - Default (no pagination params)
 *    - Custom limit and page (e.g., limit=2, page=1, 2, ...)
 * 8. Validate:
 *    - Only direct children of the parent comment are included (no deeply nested replies).
 *    - Each returned reply matches one of the created direct replies (by content/author).
 *    - The structure matches expected pagination (current, limit, records, pages).
 * 9. Add a new parent comment that has no replies, and confirm listing returns an empty paginated list for it.
 */
export async function test_api_bbs_test_list_replies_to_comment_with_valid_parent_comment_and_pagination(connection: api.IConnection) {
  // 1. Register a new user (with role - use any UUID for role for test, e.g., typia.random)
  const userRoleId = typia.random<string & tags.Format<'uuid'>>();
  const userCreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<'email'>>(),
    password: RandomGenerator.alphaNumeric(12),
    role_id: userRoleId,
    bio: RandomGenerator.paragraph()(20),
  } satisfies IBbsUsers.ICreate;
  const user = await api.functional.bbs.users.post(connection, {
    body: userCreate,
  });
  typia.assert(user);

  // 2. Create a category
  const categoryCreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(30),
  } satisfies bbsCategories.ICreate;
  const category = await api.functional.bbs.categories.post(connection, { body: categoryCreate });
  typia.assert(category); 

  // 3. Create new post in the category
  const postCreate = {
    category_id: category.id,
    title: RandomGenerator.paragraph()(6),
    content: RandomGenerator.content()(30),
  } satisfies bbsPosts.ICreate;
  const post = await api.functional.bbs.posts.post(connection, { body: postCreate });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentCommentBody = {
    content: RandomGenerator.paragraph()(10),
  } satisfies bbsComments.ICreate;
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: parentCommentBody,
  });
  typia.assert(parentComment);

  // 5. Create several direct replies to the parent comment
  const directReplies: IBbsCommentReply[] = [];
  const directReplyContents: string[] = [];
  const directReplyCount = 5;
  for (let i = 0; i < directReplyCount; ++i) {
    const replyContent = RandomGenerator.paragraph()(5 + i);
    directReplyContents.push(replyContent);
    const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
      commentId: parentComment.id,
      body: { content: replyContent } satisfies IBbsCommentReply.ICreate,
    });
    typia.assert(reply);
    directReplies.push(reply);
  }

  // 6. Create a nested reply to the first direct reply, to check only direct children are listed
  const nestedReplyContent = RandomGenerator.paragraph()(7);
  const nestedReply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: directReplies[0].id,
    body: { content: nestedReplyContent } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(nestedReply);

  // 7. List direct replies to parent comment with different pagination and filtering
  // 7a. Default (no pagination)
  const defaultRepliesPage = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: {},
  });
  typia.assert(defaultRepliesPage);
  TestValidator.equals("defaultRecordsCount")(directReplyCount)(defaultRepliesPage.pagination.records);

  // 7b. Paginate with custom limit (e.g., limit=2, implement two pages)
  const limit = 2;
  const repliesPage1 = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: { limit, page: 1 },
  });
  typia.assert(repliesPage1);
  TestValidator.equals("pagination.limit")(limit)(repliesPage1.pagination.limit);
  TestValidator.equals("pagination.current")(1)(repliesPage1.pagination.current);

  const repliesPage2 = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: parentComment.id,
    body: { limit, page: 2 },
  });
  typia.assert(repliesPage2);
  TestValidator.equals("pagination.limit")(limit)(repliesPage2.pagination.limit);
  TestValidator.equals("pagination.current")(2)(repliesPage2.pagination.current);

  // Validate only direct replies are included on any page, not nested ones
  for (const p of [defaultRepliesPage, repliesPage1, repliesPage2]) {
    for (const reply of p.data) {
      TestValidator.equals("parent_id")(parentComment.id)(reply.parent_id);
      TestValidator.predicate("reply must be among direct replies")(
        directReplyContents.includes(reply.content),
      );
    }
  }

  // 8. Add a parent comment with no replies and confirm listing is empty
  const noReplyParentBody = {
    content: RandomGenerator.paragraph()(8),
  } satisfies bbsComments.ICreate;
  const noReplyParent = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: noReplyParentBody,
  });
  typia.assert(noReplyParent);

  const emptyReplies = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
    commentId: noReplyParent.id,
    body: {},
  });
  typia.assert(emptyReplies);
  TestValidator.equals("empty reply list")(0)(emptyReplies.pagination.records);
  TestValidator.equals("empty data count")(0)(emptyReplies.data.length);
}

