import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";
import type { IPageIBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsCommentReply";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing replies to a deleted (soft-deleted) parent comment.
 *
 * Verifies system error handling and access control when requesting the list of replies for a comment that has been marked as deleted. This test ensures that no replies are returned for a soft-deleted parent comment and that the API enforces proper access restrictions, returning either an empty list or an appropriate error message.
 *
 * Detailed steps:
 * 1. Register a new user account to act as the author for all subsequent actions.
 * 2. Create a discussion category for posts.
 * 3. Create a post within the category as the test context.
 * 4. As the user, add a comment to the created post.
 * 5. Soft-delete (mark as deleted) the created comment using the delete comment endpoint.
 * 6. Attempt to retrieve replies to the deleted parent comment using the replies-listing endpoint.
 * 7. Validate that the operation returns either an empty result set or an error consistent with access denial or logical constraint.
 *
 * The test specifically verifies that replies to a deleted comment are inaccessible, preventing logical violations of the discussion structure and upholding moderation boundaries.
 */
export async function test_api_bbs_test_list_replies_to_deleted_parent_comment(connection: api.IConnection) {
  // 1. Register a new user account to act as author
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: `${RandomGenerator.alphaNumeric(8)}@test.com`,
      password: RandomGenerator.alphaNumeric(12),
      role_id: userRoleId,
      bio: null,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a discussion category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a post within the category by the user
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.paragraph()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a comment to the created post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
      parent_id: null
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. Soft-delete (mark as deleted) the newly created parent comment
  await api.functional.bbs.posts.comments.eraseByPostidAndId(connection, {
    postId: post.id,
    id: comment.id,
  });

  // 6. Attempt to list replies to the deleted parent comment
  let errorCaught = false;
  try {
    const replyPage = await api.functional.bbs.comments.comments.patchByCommentid(connection, {
      commentId: comment.id,
      body: {}, // No pagination/filter fields needed for minimal query
    });
    typia.assert(replyPage);
    // 7. Validation: Must return empty array if not an error
    TestValidator.equals("no replies for deleted comment")(0)(replyPage.data.length);
  } catch (exp) {
    errorCaught = true;
    TestValidator.predicate("error is HttpError or logic-blocked")(!!exp);
  }
}

