import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test successful retrieval of reply details for a valid reply under a parent comment.
 *
 * This test covers the full normal business scenario for fetching the detail of a nested reply in the comments table:
 * 1. Register a new user (for all actions).
 * 2. Create a BBS category (needed for post creation).
 * 3. Create a new post under that category.
 * 4. Create a top-level comment on the post.
 * 5. Create a reply to the top-level comment (the target of the GET operation).
 * 6. Retrieve the reply via GET /bbs/comments/{commentId}/comments/{id} using the correct parent comment ID and reply ID.
 * 7. Check that the response contains all required IBbsCommentReply fields, that the content/metadata matches what was posted, and ensure no confidential/sensitive fields are present in the API response (e.g., password hashes, internal-only audit fields).
 */
export async function test_api_bbs_comments_test_get_reply_details_with_valid_reply_and_permission(connection: api.IConnection) {
  // 1. Register a new user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: RandomGenerator.alphaNumeric(10) + "@example.com",
      password: "Password123!",
      // For most systems default to member role: Use typia.random<string & tags.Format<"uuid">>() for role_id
      role_id: typia.random<string & tags.Format<"uuid">>()
    },
  });
  typia.assert(user);

  // 2. Create a BBS category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(6),
      description: RandomGenerator.alphaNumeric(24)
    }
  });
  typia.assert(category);

  // 3. Create a post in that category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(8),
      content: RandomGenerator.content()(2)(),
    }
  });
  typia.assert(post);

  // 4. Add a top-level comment to the post
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(4),
    },
  });
  typia.assert(comment);

  // 5. Create a reply to that comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.paragraph()(4),
    },
  });
  typia.assert(reply);

  // 6. Retrieve the reply using parent commentId and reply.id
  const output = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });
  typia.assert(output);

  // 7. Validate response fields and content
  TestValidator.equals("reply id")(reply.id)(output.id);
  TestValidator.equals("parent_id")(reply.parent_id ?? null)(output.parent_id ?? null);
  TestValidator.equals("user_id (author)")(reply.user_id)(output.user_id);
  TestValidator.equals("post_id")(reply.post_id)(output.post_id);
  TestValidator.equals("content matches")(reply.content)(output.content);
  TestValidator.equals("deleted_at")(reply.deleted_at ?? null)(output.deleted_at ?? null);
  // check some required audit timestamps
  if(!output.created_at || !output.updated_at) throw new Error("created_at/updated_at must be defined");
  // Ensure no sensitive/internal fields leak (only check known model)
  const allowedKeys = ["id","user_id","post_id","parent_id","content","created_at","updated_at","deleted_at"];
  for (const key of Object.keys(output)) {
    if(!allowedKeys.includes(key)) throw new Error("Response leaks non-schema field: " + key);
  }
}

