 *
 * 이 테스트는 부모 댓글 아래에 실제로 존재하는 답글의 상세 정보를 정상적으로 조회할 수 있는 케이스를 검증합니다.
 * 
 * 비즈니스 흐름은 다음과 같습니다:
 * 1. 신규 유저를 생성합니다(모든 등록/조회 작업에 사용).
 * 2. 게시글을 작성할 카테고리를 새로 만듭니다.
 * 3. 해당 카테고리에 새로운 포스트를 등록합니다.
 * 4. 포스트에 1차(최상위) 댓글을 남깁니다.
 * 5. 1차 댓글(부모) 아래에 답글(2차 댓글)을 작성합니다(이때 답글 id, parent_id 확보).
 * 6. /bbs/comments/{commentId}/comments/{id} 엔드포인트로 답글의 상세정보를 조회합니다.
 * 7. 반환 데이터가 답글 생성 시점 정보와 일치하는지(모든 필드), 추가/불필요/민감 정보 노출이 없는지 검증합니다.
 */
export async function test_api_bbs_comments_test_get_reply_details_with_valid_reply_and_permission(
  connection: api.IConnection,
) {
  // 1. 신규 유저 생성
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: RandomGenerator.alphaNumeric(10) + "@example.com",
      password: "Password123!",
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. 카테고리 등록
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(6),
      description: RandomGenerator.alphaNumeric(24),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. 포스트 등록
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(8),
      content: RandomGenerator.content()(2)(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. 최상위 댓글 등록
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(4),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. 1차 댓글(부모)에 답글 등록
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.paragraph()(4),
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. 답글 상세 조회
  const output = await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });
  typia.assert(output);

  // 7. 필드 일치/불필요 정보 미노출 검증
  TestValidator.equals("reply id")(reply.id)(output.id);
  TestValidator.equals("parent_id")(reply.parent_id ?? null)(output.parent_id ?? null);
  TestValidator.equals("user_id")(reply.user_id)(output.user_id);
  TestValidator.equals("post_id")(reply.post_id)(output.post_id);
  TestValidator.equals("content")(reply.content)(output.content);
  TestValidator.equals("deleted_at")(reply.deleted_at ?? null)(output.deleted_at ?? null);

  // created_at/updated_at 필수 존재
  if (!output.created_at || !output.updated_at)
    throw new Error("created_at/updated_at must be defined");

  // 스키마 정의 외 불필요 필드 노출 없음 검증
  const allowedKeys = [
    "id",
    "user_id",
    "post_id",
    "parent_id",
    "content",
    "created_at",
    "updated_at",
    "deleted_at",
  ];
  for (const key of Object.keys(output)) {
    if (!allowedKeys.includes(key))
      throw new Error("Response leaks non-schema field: " + key);
  }
}

