import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate system behavior when attempting to retrieve the details of a reply (nested comment) that has been soft-deleted.
 *
 * This test verifies error handling and access restrictions for deleted content:
 * - It creates a user, a category, a post, a top-level comment, and a reply (nested comment).
 * - It then soft-deletes the reply.
 * - Finally, it attempts to fetch the details of the deleted reply and checks whether the system properly restricts access or marks the reply as deleted.
 *
 * Expected behavior: The system either hides the content of a soft-deleted reply or returns an error indicating that the reply is inaccessible to normal users (depending on API policy). The test ensures the resource cannot be normally accessed or its content is not shown after deletion.
 *
 * Steps:
 * 1. Register a user
 * 2. Create a category
 * 3. Create a post in the category
 * 4. Add a top-level comment to the post
 * 5. Add a reply (nested comment) to that comment
 * 6. Soft-delete the reply
 * 7. Attempt to fetch the details of the deleted reply and validate the result as per business/visibility rules
 */
export async function test_api_bbs_test_get_reply_details_for_deleted_reply(connection: api.IConnection) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphabets(10) + "@test.com",
      password: "testPw123!",
      bio: RandomGenerator.paragraph()(1),
      role_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: "Cat-" + RandomGenerator.alphaNumeric(5),
      description: RandomGenerator.paragraph()(1)
    } satisfies bbsCategories.ICreate
  });
  typia.assert(category);

  // 3. Create post in the category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()(2)
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 4. Add top-level comment to post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()(1)
    } satisfies bbsComments.ICreate
  });
  typia.assert(parentComment);

  // 5. Add reply (nested comment)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: RandomGenerator.content()(1)
    } satisfies IBbsCommentReply.ICreate
  });
  typia.assert(reply);

  // 6. Soft-delete the reply
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id
  });

  // 7. Attempt to fetch the deleted reply's details and confirm error or hidden content
  await TestValidator.error("Should not fetch details of soft-deleted reply")(
    async () => {
      await api.functional.bbs.comments.comments.getByCommentidAndId(connection, {
        commentId: parentComment.id,
        id: reply.id
      });
    }
  );
}

