import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate nested reply (threaded comment) creation by an authenticated user in the discussion board (BBS) system.
 *
 * This test covers the complete workflow for posting a reply to an existing comment. The aim is to ensure that, when prerequisites are handled correctly (user registration, category/post/comment creation), posting a reply associates it with the correct parent comment and records proper author/timestamp.
 *
 * Steps:
 * 1. Register a new user for the BBS platform, who will serve as the author for all subsequent operations.
 * 2. Create a discussion category in the BBS for the test post placement.
 * 3. Create a new post by the registered user within the created category.
 * 4. Add a new comment to the post (as the parent for our threaded reply).
 * 5. Submit a nested reply to the parent comment with valid content.
 * 6. Assert that the reply's data:
 *    - has the correct content,
 *    - is associated to the correct parent comment (via parent_id),
 *    - properly records author information (user_id matches the registered user),
 *    - includes a valid created_at timestamp.
 */
export async function test_api_bbs_test_create_reply_to_comment_with_valid_auth_and_data(
  connection: api.IConnection,
) {
  // 1. Register a new user (author of all subsequent items).
  // Choose a random role_id for now - in a real scenario, you might fetch an actual member role UUID.
  const roleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      role_id: roleId,
      bio: RandomGenerator.paragraph()(10),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create a discussion category.
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(20),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create a new post by the user in the new category.
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(5),
      content: RandomGenerator.content()(2)(30),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add a parent comment to the post.
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()(1)(40),
      // parent_id omitted for top-level comment
    } satisfies bbsComments.ICreate,
  });
  typia.assert(parentComment);

  // 5. Submit a nested reply (threaded comment) to the parent comment.
  const replyContent = RandomGenerator.content()(1)(50);
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: replyContent,
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. Assertions -- reply should be linked to parent and have proper author/timestamp fields
  TestValidator.equals("parent_id as parent's id")(parentComment.id)(reply.parent_id);
  TestValidator.equals("user_id matches registered user")(user.id)(reply.user_id);
  TestValidator.equals("post_id is correct")(post.id)(reply.post_id);
  TestValidator.equals("content exactly")(replyContent)(reply.content);
  TestValidator.predicate("created_at is valid timestamp")(
    typeof reply.created_at === "string" && !isNaN(Date.parse(reply.created_at)),
  );
}

