import { tags } from "typia";

/**
 * A single reply comment/nested reply object.
 *
 * Represents a direct response to a parent comment (or a top-level post reply).
 * Includes all evidence required for auditing, threading, and moderation.
 * Referenced from threaded/nested replies in comments Prisma model.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IBbsCommentReply = {
  /**
   * Unique identifier for the comment reply.
   *
   * Primary key from the comments Prisma model. Used for programmatic
   * operations and API lookups.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Identifier for the authoring user of this reply comment.
   *
   * References users.id. Used for attribution, audit, and profile summary
   * features.
   */
  user_id: string & tags.Format<"uuid">;

  /**
   * Identifier for the parent post to which this reply (comment) belongs.
   *
   * References posts.id. Required for evidence/auditing, threading context,
   * and navigation (see ERD and comments model).
   */
  post_id: string & tags.Format<"uuid">;

  /**
   * Identifier for the parent comment if this is a reply (threading
   * hierarchy). Null for top-level (post) replies, set for nested replies.
   *
   * Mapped from comments.parent_id in the Prisma schema.
   */
  parent_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Reply body text for this comment. Business meaning: user-supplied message
   * or opinion as per 'content' in Prisma model.
   */
  content: string;

  /**
   * Timestamp for when the reply comment was created (ISO 8601 format).
   *
   * Taken from comments.created_at. Important for audit/history, proper
   * ordering, and moderation evidence.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp for last edit. Reflects edit history and transparency for
   * users/moderators. Maps to comments.updated_at field.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * If set, indicates the reply was deleted (soft delete logic). Used for
   * moderation/audit preservation. Matches comments.deleted_at.
   */
  deleted_at?: (string & tags.Format<"date-time">) | null;
};
export namespace IBbsCommentReply {
  /**
   * Payload for creating a new reply (nested comment) to a parent comment.
   * Enforces required comment body, referenced from comments Prisma model and
   * requirements analysis.
   */
  export type ICreate = {
    /**
     * Reply content (body text). User-supplied message or opinion
     * contributed as a nested reply. From comments.content Prisma field.
     */
    content: string;
  };

  /**
   * Edit/update payload for a reply comment (nested thread). Allows the reply
   * content to be changed. Ownership and audit rules apply.
   */
  export type IUpdate = {
    /**
     * Updated reply content (body text). Used when editing reply within
     * allowed window, per requirements.
     */
    content: string;
  };
}

