import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * 답글(대댓글) 수정 권한 및 데이터 반영 유효성 테스트
 *
 * 1. ownerUser, otherUser 계정 두 개를 등록한다.
 * 2. 카테고리를 생성한다.
 * 3. ownerUser가 게시글을 생성한다.
 * 4. ownerUser가 해당 게시글에 상위 댓글(Comment)을 작성한다.
 * 5. ownerUser가 상위 댓글에 답글(Reply)을 단다.
 * 6. ownerUser가 답글 내용을 수정하여 업데이트를 요청한다.
 *    - 결과의 content와 updated_at이 실제로 반영되고 user_id(작성자)가 동일한지 검증한다.
 * 7. otherUser가 동일 답글을 수정 시도하면 권한 오류를 반환하는지 검증한다.
 */
export async function test_api_bbs_test_update_reply_with_valid_owner_and_data(
  connection: api.IConnection,
) {
  // 1. ownerUser, otherUser 회원 가입
  const ownerUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: RandomGenerator.alphaNumeric(6) + "@example.com",
      password: RandomGenerator.alphaNumeric(10),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(ownerUser);

  const otherUser = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(7),
      email: RandomGenerator.alphaNumeric(7) + "@example.com",
      password: RandomGenerator.alphaNumeric(11),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(otherUser);

  // 2. 카테고리 생성
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: "테스트카테고리" + RandomGenerator.alphabets(3),
      description: "E2E 테스트용 카테고리",
    },
  });
  typia.assert(category);

  // 3. ownerUser로 게시글 작성
  // (토큰 스위칭 생략: 테스트 계정 간 context 스위칭 처리 환경 전제)
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "E2E 테스트 게시글 - " + RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. 상위 댓글 작성 (ownerUser)
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(
    connection,
    {
      postId: post.id,
      body: {
        content: "상위 댓글: " + RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(parentComment);

  // 5. 답글 작성 (ownerUser)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(
    connection,
    {
      commentId: parentComment.id,
      body: {
        content: "초기 답글: " + RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(reply);

  // 6. 답글 내용 업데이트 (ownerUser)
  const newContent = "수정된 답글: " + RandomGenerator.content()()();
  await TestUtil.switchUser(connection, ownerUser);
  const updatedReply = await api.functional.bbs.comments.comments.putByCommentidAndId(
    connection,
    {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: newContent,
      },
    },
  );
  typia.assert(updatedReply);
  // - content 반영, updated_at 갱신, user_id 동일(작성자 불변)
  TestValidator.equals("content 변경 반영됨")(newContent)(updatedReply.content);
  TestValidator.notEquals("updated_at 갱신됨")(reply.updated_at)(updatedReply.updated_at);
  TestValidator.equals("작성자 동일")(reply.user_id)(updatedReply.user_id);

  // 7. 권한 없는 사용자로 답글 수정 시도 (실패, 권한 오류)
  await TestUtil.switchUser(connection, otherUser);
  await TestValidator.error("권한 없는 사용자 답글 수정 실패")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: "타인이 수정하려는 내용: " + RandomGenerator.content()()(),
      },
    }),
  );
}

