import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * E2E test for invalid reply update cases:
 *
 * - Should fail to update a reply if the submitted content is invalid (e.g., empty string)
 * - Should fail to update a reply if the reply has been soft-deleted (deleted_at set)
 *
 * Workflow:
 * 1. Register a new user (for content ownership)
 * 2. Create a new category
 * 3. Create a new post under the created category
 * 4. Add a parent comment to the post
 * 5. Add a reply (nested comment) to the parent comment
 * 6. (Invalid update) Attempt to update the reply with an empty content field, expect error
 * 7. Delete the reply (soft delete)
 * 8. (Invalid update) Attempt to update the deleted reply, expect error (cannot update deleted replies)
 */
export async function test_api_bbs_test_update_reply_with_invalid_content_or_deleted_reply(connection: api.IConnection) {
  // 1. Register user for content ownership
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const username = RandomGenerator.alphabets(8);
  const email = `${RandomGenerator.alphabets(5)}@example.com`;
  const password = "TestPassw0rd!";
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username,
      email,
      password,
      bio: "Test user for reply update failures",
      role_id: userRoleId
    }
  });
  typia.assert(user);

  // 2. Create a category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: "Category_" + RandomGenerator.alphabets(6),
      description: "Category for reply update test."
    }
  });
  typia.assert(category);

  // 3. Create a post under the created category
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: "Test Post for Invalid Reply Update",
      content: "This post is used to test updating replies in error situations."
    }
  });
  typia.assert(post);

  // 4. Add a parent comment to the post
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: "Test parent comment."
    }
  });
  typia.assert(parentComment);

  // 5. Add a reply (nested comment) to the parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: "Initial reply content."
    }
  });
  typia.assert(reply);

  // 6. Attempt to update reply with invalid (empty) content — should fail
  await TestValidator.error("Updating reply with empty content should fail")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: ""
      }
    })
  );

  // 7. Delete the reply (soft-delete)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id
  });

  // 8. Attempt to update deleted reply — should fail
  await TestValidator.error("Updating a deleted reply should fail")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: parentComment.id,
      id: reply.id,
      body: {
        content: "Should not be able to update after deletion."
      }
    })
  );
}

