import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * 권한이 없는 유저가 자신이 소유하지 않은 대댓글(reply/nested comment)을 수정(update) 시도할 때 적절한 권한 에러를 검증하는 테스트입니다.
 *
 * 이 시나리오에서는 다음의 과정을 밟아 실제 권한 에러를 확인합니다.
 *
 * 1. 두 명의 사용자(유저)를 회원가입 처리(권한 분리를 위함)
 * 2. 게시판 카테고리 등록 (게시글 생성 전 필요)
 * 3. 첫 번째 유저로 로그인/인증하여 게시글 생성
 * 4. 생성된 게시글에 첫 번째 유저가 댓글 등록
 * 5. 첫 번째 유저가 해당 댓글에 대댓글(답글) 작성 (대댓글 소유자)
 * 6. 두 번째 유저로 로그인 후, 첫 번째 유저가 작성한 대댓글을 수정 시도 (실패해야 함)
 * 7. 인증 없이(비회원) 첫 번째 유저 대댓글을 수정 시도 (실패해야 함)
 * 8. 각 시도 때마다 API로부터 적절한 권한 에러(예: 403 또는 401 Unauthorized 등) 반환을 검증
 */
export async function test_api_bbs_test_update_reply_by_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. 두 명의 사용자 회원가입 처리
  // (테스트에 사용할 권한 분리용 유저 데이터 준비)
  // - userA: 대댓글 소유자
  // - userB: 타인(권한 없는 유저)
  //
  // 유저 롤(role)은 적절한 권한이 있는 일반 사용자 UUID를 임의값으로 사용
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userAPassword = "userAPassword!1";
  const userBPassword = "userBPassword!2";

  const userA = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: userAEmail,
      password: userAPassword,
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: userBEmail,
      password: userBPassword,
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // 2. 게시판 카테고리 등록 (관리자 권한 필요 가정, 테스트에서는 임의값 등록)
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. userA로 인증 후 게시글 생성
  await api.functional.bbs.users.post.login(connection, {
    body: { email: userAEmail, password: userAPassword },
  });
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.content()()(1),
    },
  });
  typia.assert(post);

  // 4. userA가 본인 게시글에 댓글 등록
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()(1) },
  });
  typia.assert(comment);

  // 5. userA가 해당 댓글에 대댓글 등록 (본인이 소유)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: { content: RandomGenerator.paragraph()(1) },
  });
  typia.assert(reply);

  // 6. userB로 로그인 후, userA가 쓴 대댓글을 수정 시도 (권한 없음)
  await api.functional.bbs.users.post.login(connection, {
    body: { email: userBEmail, password: userBPassword },
  });
  await TestValidator.error("userB는 타인 대댓글 수정 불가")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: comment.id,
      id: reply.id,
      body: { content: "해킹 시도" } satisfies IBbsCommentReply.IUpdate,
    }),
  );

  // 7. 인증 없이(비회원 상태) userA의 대댓글 수정 시도 (권한 없음)
  // 로그아웃 처리: connection 객체의 인증 헤더 제거
  delete connection.headers?.Authorization;
  await TestValidator.error("비회원은 대댓글 수정 불가")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: comment.id,
      id: reply.id,
      body: { content: "게스트 해킹 시도" } satisfies IBbsCommentReply.IUpdate,
    }),
  );
}

