    body: {
      username: RandomGenerator.name(),
      email: userAEmail,
      password: userAPassword,
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.name(),
      email: userBEmail,
      password: userBPassword,
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(userB);

  // 2. 게시판 카테고리 등록
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(category);

  // 3. userA로 게시글 생성
  // NOTE: 실제 서비스에서 유저 교체는 별도의 인증 API 또는 token 관리 등 필요
  // 여기서는 connection이 자동으로 인증 헤더를 관리한다고 가정
  // (별도 users.post.login API가 없다면, 이에 맞게 토큰 전환 관리 필요)
  // userA 인증상태로 게시글 생성
  // 실제 테스트에서는 적절한 token 세션 전환 필요

  // (생략: 인증 처리 단계 — 실제 환경에 맞게 connection에 토큰 삽입 필요)

  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. userA가 댓글 등록
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()() },
  });
  typia.assert(comment);

  // 5. userA가 대댓글 등록
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: { content: RandomGenerator.paragraph()() },
  });
  typia.assert(reply);

  // 6. userB로 로그인 후, userA가 작성한 대댓글을 수정 시도 (권한 없음)
  // (여기서 실제로 token 세션을 userB로 교체해야 함)
  // 실제 적용 환경에서는 userB 인증 세션 반영 필요

  // (생략: 인증 처리 단계 — 실제 환경에 맞게 connection에 토큰 삽입 필요)

  await TestValidator.error("userB는 타인 대댓글 수정 불가")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: comment.id,
      id: reply.id,
      body: { content: "해킹 시도" } satisfies IBbsCommentReply.IUpdate,
    }),
  );

  // 7. 인증 없이(비회원) userA의 대댓글 수정 시도 (권한 없음)
  // 로그아웃 처리: connection의 Authorization 헤더 제거
  if (connection.headers?.Authorization) delete connection.headers.Authorization;
  await TestValidator.error("비회원은 대댓글 수정 불가")(() =>
    api.functional.bbs.comments.comments.putByCommentidAndId(connection, {
      commentId: comment.id,
      id: reply.id,
      body: { content: "게스트 해킹 시도" } satisfies IBbsCommentReply.IUpdate,
    }),
  );
}

