import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Test if an author can soft-delete (not hard-delete) their own reply comment, and verify its visibility and status after deletion.
 *
 * This validates that the deletion logic for nested replies is correctly implemented so that a user who wrote a reply to a comment can delete (soft delete) their reply, while ensuring proper audit and visibility rules: (1) the reply must be marked as deleted, (2) it must not be physically removed (no hard deletion), and (3) after deletion, regular users cannot access its content.
 *
 * Step-by-step process:
 * 1. Register a new user (reply author)
 * 2. Create a new category
 * 3. Create a new post in the category (as the author)
 * 4. Add a top-level (parent) comment to the post
 * 5. Add a reply (nested comment) to the parent comment
 * 6. Delete (soft-delete) the reply using its author account
 * 7. Attempt to fetch the deleted reply as a normal user and verify access is denied or the reply is not retrievable
 * 8. Verify, likely via parent comment thread or admin, that reply remains in soft-deleted state (deleted_at set, not removed)
 */
export async function test_api_bbs_test_delete_reply_with_owner_permission(connection: api.IConnection) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.alphaNumeric(5) + '@example.com',
      password: 'Password1!',
      role_id: typia.random<string & tags.Format<'uuid'>>()
    } satisfies IBbsUsers.ICreate
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(1)
    }
  });
  typia.assert(category);

  // 3. Create post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()()
    } satisfies bbsPosts.ICreate
  });
  typia.assert(post);

  // 4. Create parent comment
  const parentComment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.content()()()
    }
  });
  typia.assert(parentComment);

  // 5. Create reply to parent comment
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: parentComment.id,
    body: {
      content: RandomGenerator.content()()()
    }
  });
  typia.assert(reply);

  // 6. Delete the reply (soft delete)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: parentComment.id,
    id: reply.id
  });

  // 7. Try to fetch reply as normal user (should not be accessible or visible)
  // -- Assume there is no direct get endpoint, so this would be checked either via thread listing or admin API not provided, so omit direct check.

  // 8. (Optional) If reply can be listed under parent, verify deleted_at is set (API not provided; would check if available)

  // Note: For this scenario, assert success of deletion and that no errors occurred up to this point.
}

