import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate permission enforcement on deleting a reply comment as a non-owner or unauthenticated user.
 *
 * This test ensures the BBS system enforces that only the reply's owner or a moderator can delete replies.
 *
 * Steps:
 * 1. Register two users (owner and other).
 * 2. Create a test category (by one user).
 * 3. Create a post in the test category.
 * 4. Add a base comment to the post.
 * 5. As the first user, add a reply to the base comment.
 * 6. Attempt to delete the reply using the second user's credentials — expect a permission error.
 * 7. Attempt to delete the reply without authentication — expect a permission error.
 */
export async function test_api_bbs_test_delete_reply_by_unauthorized_user(connection: api.IConnection) {
  // 1. Register two users
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const user1Email = `${RandomGenerator.alphaNumeric(5)}1@example.com`;
  const user2Email = `${RandomGenerator.alphaNumeric(5)}2@example.com`;
  const user1 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: user1Email,
      password: "Password1!",
      role_id: roleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user1);
  const user2 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: user2Email,
      password: "Password2!",
      role_id: roleId
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user2);
  // Assume: connection now carries authentication for user1 (owner), or provide mechanism to login as needed.

  // 2. Create test category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1)
    }
  });
  typia.assert(category);

  // 3. Create a post for context
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.paragraph()(2),
    }
  });
  typia.assert(post);

  // 4. Create a base comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()(1) }
  });
  typia.assert(comment);

  // 5. Create a reply as the first user
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: { content: RandomGenerator.paragraph()(1) }
  });
  typia.assert(reply);

  // 6. Attempt deletion by second user (should fail)
  // Switch authentication to user2 (simulate login if possible)
  connection.headers = { ...connection.headers, Authorization: `Bearer ${user2.id}` }; // Example; actual login may set a token
  await TestValidator.error("Non-owner cannot delete reply")(() =>
    api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
      commentId: comment.id,
      id: reply.id
    })
  );

  // 7. Attempt deletion without authentication (no Authorization header)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("Unauthenticated cannot delete reply")(() =>
    api.functional.bbs.comments.comments.eraseByCommentidAndId(unauthConn, {
      commentId: comment.id,
      id: reply.id
    })
  );
}

