import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate permission enforcement on deleting a reply comment as a non-owner or unauthenticated user.
 *
 * This test ensures that only the reply's owner or a moderator is permitted to delete reply comments on the BBS. All other users and anonymous attempts should result in permission errors.
 *
 * Steps:
 * 1. Register two users (the reply owner and an unauthorized user).
 * 2. Create a test category (using the owner account).
 * 3. Post a discussion thread under the category.
 * 4. Add a base comment to the post.
 * 5. Have the owner post a reply to the base comment.
 * 6. Switch to the second user's account and attempt to delete the reply — validate a permission error occurs.
 * 7. Remove all authentication and try deleting the reply — validate a permission error occurs.
 */
export async function test_api_bbs_test_delete_reply_by_unauthorized_user(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register two users (owner and unauthorized)
  const roleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const user1Email = `${RandomGenerator.alphaNumeric(8)}_u1@example.com`;
  const user2Email = `${RandomGenerator.alphaNumeric(8)}_u2@example.com`;

  const user1 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: user1Email,
      password: "Password1!",
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user1);

  const user2 = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: user2Email,
      password: "Password2!",
      role_id: roleId,
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user2);

  // Simulate login as user1: in a real test suite, implement proper authentication to switch users
  const user1Connection = {
    ...connection,
    headers: { ...connection.headers, Authorization: `Bearer user1-${user1.id}` },
  };

  // 2. Create a test category as user1
  const category = await api.functional.bbs.categories.post(user1Connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(category);

  // 3. Create a post for context
  const post = await api.functional.bbs.posts.post(user1Connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      content: RandomGenerator.paragraph()(2),
    },
  });
  typia.assert(post);

  // 4. Create a base comment as user1
  const comment = await api.functional.bbs.posts.comments.postByPostid(user1Connection, {
    postId: post.id,
    body: { content: RandomGenerator.paragraph()(1) },
  });
  typia.assert(comment);

  // 5. Create a reply as user1
  const reply = await api.functional.bbs.comments.comments.postByCommentid(user1Connection, {
    commentId: comment.id,
    body: { content: RandomGenerator.paragraph()(1) },
  });
  typia.assert(reply);

  // 6. Attempt deletion by the unauthorized user (user2)
  const user2Connection = {
    ...connection,
    headers: { ...connection.headers, Authorization: `Bearer user2-${user2.id}` },
  };
  await TestValidator.error("Non-owner cannot delete reply")(() =>
    api.functional.bbs.comments.comments.eraseByCommentidAndId(user2Connection, {
      commentId: comment.id,
      id: reply.id,
    })
  );

  // 7. Attempt deletion without authentication (no Authorization header)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("Unauthenticated cannot delete reply")(() =>
    api.functional.bbs.comments.comments.eraseByCommentidAndId(unauthConn, {
      commentId: comment.id,
      id: reply.id,
    })
