import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBbsUsers } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUsers";
import type { IBbsUserRoles } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsUserRoles";
import type { bbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsCategories";
import type { IBbsCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCategories";
import type { bbsPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsPosts";
import type { bbsComments } from "@ORGANIZATION/PROJECT-api/lib/structures/bbsComments";
import type { IBbsCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsCommentReply";

/**
 * Validate system behavior when attempting to delete a reply that has already been soft-deleted.
 *
 * Business scenario: The system should not allow deleting a reply that has already been deleted (soft-deleted). It must return an error (such as not found or already deleted) for subsequent delete attempts. This confirms moderation logic is enforced.
 *
 * Steps:
 * 1. Register a user – who will author all following actions.
 * 2. Create a category for the post context.
 * 3. Create a discussion post linked to that category.
 * 4. Add a parent comment to the post.
 * 5. Add a reply (child comment) to the parent comment.
 * 6. Delete the reply (should soft-delete successfully).
 * 7. Attempt to delete the same reply again and confirm the system throws an error (already deleted/not found).
 */
export async function test_api_bbs_test_delete_reply_that_is_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register user
  const user = await api.functional.bbs.users.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: RandomGenerator.alphabets(6) + "@example.com",
      password: RandomGenerator.alphaNumeric(12),
      role_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IBbsUsers.ICreate,
  });
  typia.assert(user);

  // 2. Create category
  const category = await api.functional.bbs.categories.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    } satisfies bbsCategories.ICreate,
  });
  typia.assert(category);

  // 3. Create post
  const post = await api.functional.bbs.posts.post(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
    } satisfies bbsPosts.ICreate,
  });
  typia.assert(post);

  // 4. Add parent comment
  const comment = await api.functional.bbs.posts.comments.postByPostid(connection, {
    postId: post.id,
    body: {
      content: RandomGenerator.paragraph()(),
    } satisfies bbsComments.ICreate,
  });
  typia.assert(comment);

  // 5. Add reply (child comment)
  const reply = await api.functional.bbs.comments.comments.postByCommentid(connection, {
    commentId: comment.id,
    body: {
      content: RandomGenerator.paragraph()(),
    } satisfies IBbsCommentReply.ICreate,
  });
  typia.assert(reply);

  // 6. Delete the reply (first time, should succeed)
  await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
    commentId: comment.id,
    id: reply.id,
  });

  // 7. Attempt to delete the reply again - expect an error
  await TestValidator.error("attempt to delete already-deleted reply must fail")(
    async () => {
      await api.functional.bbs.comments.comments.eraseByCommentidAndId(connection, {
        commentId: comment.id,
        id: reply.id,
      });
    },
  );
}

